INSERT INTO glossary_entries (source_no, language, letter, term, english, definition) VALUES
    (193, 'ru', 'А', 'Аварийное переключение', 'Failover', 'Переключение на резервный контур/компонент ИТ-системы'),
    (13, 'ru', 'А', 'Активы Клиента', 'Client Assets', 'денежные средства, ценные бумаги Клиента, находящиеся на Брокерском счёте, драгоценные металлы, а также денежные средства, ценные бумаги, драгоценные металлы Клиента, которые должны поступить на Брокерский счет в результате расчётов по сделкам, заключённым Брокером в интересах Клиента.'),
    (112, 'ru', 'А', 'Активы клиента (в контексте маржинальных сделок)', 'Client’s Assets (Confirmed)', 'Денежные средства и ценные бумаги клиента, соответствующие требованиям компании и доступные для обеспечения.'),
    (95, 'ru', 'А', 'Аналитическая стоимость', 'Analytical Value', 'Переоценённая рыночная или расчётная справедливая стоимость ценных бумаг в маржинальной сделке с учётом начисленных процентов.'),
    (1, 'ru', 'А', 'Анкета клиента', 'Client Questionnaire', 'собирательное понятие для Анкеты физического лица и Анкеты юридического лица (формы в Приложении № 1 к Договору).'),
    (26, 'ru', 'Б', 'Базовая валюта / Целевая валюта', 'Base Currency / Target Currency', 'Валюта, из которой (в которую) осуществляется конвертация или выражено обязательство.'),
    (80, 'ru', 'Б', 'Базовый актив', 'Underlying Asset', 'финансовый инструмент, товар или показатель, на котором основывается производный финансовый инструмент (дериватив). Это может быть ценная бумага, товар, валюта, процентная ставка и другие показатели.'),
    (4, 'ru', 'Б', 'Банк / Банк-кастодиан', 'Bank / Custodian Bank', 'любой банк, в котором Брокер открыл банковские счета для целей осуществления расчётов по операциям Клиентов и/или собственной деятельности.'),
    (111, 'ru', 'Б', 'Безналичная операция', 'Cashless Transaction', 'Сделка, при которой расчёты осуществляются переводом без использования наличных средств.'),
    (226, 'ru', 'Б', 'Бенефициарный владелец', 'Beneficial owner', 'Физическое лицо (лица), которое в конечном итоге владеет или контролирует Клиента и/или от имени которого осуществляется сделка или операция, включая контроль через структуру собственности или иным способом, прямо или косвенно.'),
    (211, 'ru', 'Б', 'Брокер', 'Broker', 'Rioni Capital LLC (Брокер) - профессиональный участник рынка ценных бумаг, обладающий брокерской лицензией Национального банка Грузии, действующий от имени за счёт Клиента или от своего имени и за счёт Клиента при заключении сделок с Финансовыми инструментами за вознаграждение (комиссию).'),
    (212, 'ru', 'Б', 'Брокерский договор', 'Brokerage agreement', 'договор на брокерское обслуживание, заключаемый между Rioni Capital LLC (Брокером) и Клиентом, регулирующий порядок оказания Брокером услуг на финансовых рынках, открытия и ведения Брокерского счёта Клиента, а также прав и обязанностей Сторон. Неотъемлемой частью Брокерского договора являются все приложения к нему, включая настоящий Регламент (Приложение № 1 к Брокерскому договору).'),
    (14, 'ru', 'Б', 'Брокерский счёт', 'Brokerage Account', 'структурная единица группировки информации об операциях, связанных с движением Имущества Клиента, в системе внутреннего учёта Брокера, используемая, в том числе, для целей применения Тарифного плана'),
    (241, 'ru', 'Б', 'Брокер (Компания, ООО «Rioni Capital»)', 'Broker (Company, Rioni Capital LLC)', 'Брокерская компания Rioni Capital LLC (ООО «Риони Капитал»), имеющая лицензию Национального банка Грузии на осуществление брокерской деятельности и которая при заключении сделок с финансовыми инструментами действует от имени и за счёт Клиента либо от своего имени и за счёт Клиента. В части учёта прав Клиента на дематериализованные ценные бумаги Брокер действует в качестве «лица, ведущего счёт» в значении Закона Грузии «О владении дематериализованными ценными бумагами» и обеспечивает учёт указанных прав у депозитария / кастодиана.'),
    (5, 'ru', 'В', 'Валюта', 'Currency', 'Национальные или иностранные денежные единицы, включая грузинский лари.'),
    (50, 'ru', 'В', 'Валюта котировки', 'Quote Currency', 'Валюта, в которой выражена цена инструмента или производится расчёт по конверсионной сделке.'),
    (183, 'ru', 'В', 'Валютная волатильность', 'FX Volatility', 'Изменчивость валютных курсов.'),
    (151, 'ru', 'В', 'Валютные операции, связанные с инвестиционными услугами', 'FX Transactions related to Investment Services', 'Сделки с валютой, совершаемые в целях исполнения или сопровождения инвестиционных операций клиента.'),
    (182, 'ru', 'В', 'Валютный гэп', 'FX GAP', 'Несоответствие активов и обязательств в валюте.'),
    (181, 'ru', 'В', 'Валютный риск', 'FX Exposure', 'Открытая валютная позиция.'),
    (69, 'ru', 'В', 'Вариационная маржа', 'Variation Margin', 'рассчитанная Клиринговой организацией в ходе клирингового сеанса сумма денежных средств, подлежащая зачислению или списанию с Субсчёта по каждому заключённому срочному контракту и (или) Открытой позиции, сформировавшейся в ходе предыдущих клиринговых сеансов, в соответствии со Спецификацией соответствующего срочного контракта.'),
    (47, 'ru', 'В', 'Веб-сайт брокера', 'Broker’s Website', 'Официальный сайт компании (www.rioni-capital.ge), содержащий информацию и документы для клиентов.'),
    (208, 'ru', 'В', 'Вес риска', 'Risk Weight', 'Вес риска, используемый при расчете IM/MM'),
    (130, 'ru', 'В', 'Внебиржевой рынок (OTC)', 'Over-the-Counter (OTC) Market', 'Площадка или форма торговли, где сделки совершаются напрямую между контрагентами, а не через биржу.'),
    (158, 'ru', 'В', 'Волатильность', 'Volatility', 'Статистическая мера изменчивости цен.'),
    (194, 'ru', 'В', 'Время простоя', 'Downtime', 'Время недоступности сервиса/оборудования'),
    (198, 'ru', 'В', 'Вторичная маркет-дата', 'Secondary Market Data', 'Информация о ценах от агрегаторов данных'),
    (128, 'ru', 'В', 'Вторичное публичное размещение (SPO)', 'Secondary Public Offering (SPO)', 'Дополнительная эмиссия акций компании, уже обращающейся на бирже.'),
    (61, 'ru', 'В', 'Вышестоящий брокер', 'Prime Broker / Executing Broker', 'иностранный или грузинский профессиональный участник рынка, имеющий соответствующую лицензию/разрешение на осуществление брокерской деятельности и через которого Брокер исполняет Поручения Клиентов на иностранных торговых площадках и (или) организованных рынках.'),
    (177, 'ru', 'Г', 'Глубина рынка', 'Market Depth (DOM)', 'Структура стакана и индикатор ликвидности.'),
    (209, 'ru', 'Г', 'Группы риска', 'Risk Groups', 'Набор параметров системы управления рисками Брокера (СУР), применяемый к конкретному Портфелю Клиента. Перечень Групп риска и их параметры определяются Брокером и размещаются на Сайте Брокера.'),
    (180, 'ru', 'Г', 'Гэп ликвидности', 'Funding Gap', 'Разрыв между источниками ликвидности и потребностями в ликвидности.'),
    (199, 'ru', 'Д', 'Данные исполнения', 'Execution Data', 'Информация об исполнении сделок.'),
    (227, 'ru', 'Д', 'Деловые отношения', 'Business relationship', 'Отношения между отчётным лицом и Клиентом, установленные в связи с предоставлением услуг или продуктов, которые по своему характеру предполагают определённую продолжительность (включая открытие и обслуживание счёта).'),
    (124, 'ru', 'Д', 'Дематериализация', 'Dematerialization (DEMAT)', 'Перевод ценных бумаг в бездокументарную форму с учётом через депозитарий.'),
    (141, 'ru', 'Д', 'Директива 2014/65/EU о рынках финансовых инструментов (MiFID II)', 'Directive 2014/65/EU on Markets in Financial Instruments (MiFID II)', 'Основной акт ЕС, устанавливающий требования к предоставлению инвестиционных услуг, классификации клиентов и защите инвесторов.'),
    (8, 'ru', 'Д', 'Дистанционное заключение договора', 'E-Sign (Remote Agreement)', 'заключение (акцепт) Договора путём направления в адрес Брокера документов и сведений, необходимых для заключения Договора и его Приложений, в электронной форме (в том числе с использованием простой электронной подписи) посредством специального раздела Сайта, Личного кабинета или web-интерфейса Партнёра с использованием специальных технических средств, в соответствии с применимым гражданским законодательством Грузии и нормативными актами НБГ'),
    (110, 'ru', 'Д', 'Длинная позиция', 'Long Position', 'Позиция, возникающая при покупке актива с расчётом на рост его рыночной стоимости.'),
    (9, 'ru', 'Д', 'Документ, удостоверяющий личность', 'Government-Issued ID', 'один из следующих документов: • паспорт гражданина Грузии; • идентификационная карта (ID Card) гражданина Грузии; • свидетельство о рождении гражданина Грузии (для граждан Грузии в возрасте до 14 лет); • паспорт иностранного гражданина; • вид на жительство в Грузии либо иной документ, признаваемый законодательством Грузии надлежащим документом, удостоверяющим личность.'),
    (93, 'ru', 'Д', 'Дополнительная комиссия', 'Additional Fee', 'Плата, взимаемая с клиента при нарушении коэффициента достаточности капитала (CAR) для покрытия расходов компании.'),
    (157, 'ru', 'Д', 'Доходность', 'Return', 'Изменение стоимости инструмента за период.'),
    (10, 'ru', 'Д', 'Доход по ценным бумагам', 'Interest Income', 'любые денежные средства и/или иное имущество, полученные по ценным бумагам, включая, но не ограничиваясь, дивидендами, процентами, накопленным купонным доходом (НКД), иными видами дохода и распределений, выплачиваемых (передаваемых) эмитентом ценных бумаг или иным лицом, выдавшим ценные бумаги, за вычетом налогов, сборов и иных обязательных удержаний.'),
    (11, 'ru', 'Е', 'Еврооблигации', 'Eurobond', 'облигации, номинированные в валюте, отличной от валюты страны эмитента, выпускаемые зарубежными правительствами и иными органами власти, международными организациями, крупными корпорациями и иными юридическими лицами и обращающиеся на международных рынках капитала.'),
    (188, 'ru', 'З', 'Задержка исполнения', 'Execution Latency', 'Задержка в исполнении клиентских поручений'),
    (187, 'ru', 'З', 'Задержка маркет-даты', 'Market Data Delay', 'Задержка информации об актуальных рыночных котировках'),
    (173, 'ru', 'З', 'Задержка расчётов', 'Settlement Delay', 'Задержка клиринга. Задержка расчетов по сделкам и операциям'),
    (146, 'ru', 'З', 'Закон об инвестиционных компаниях 1940 г. и Закон об инвестиционных консультантах 1940 г.', 'Investment Company Act of 1940 & Investment Advisers Act of 1940', 'Нормативная база SEC, регулирующая деятельность фондов и инвестиционных советников; аналог PRIIPs в части раскрытия рисков и обязанностей перед розничными инвесторами.'),
    (144, 'ru', 'З', 'Закон о рынке ценных бумаг 1934 г.', 'Securities Exchange Act of 1934', 'Базовый закон США, регулирующий вторичный рынок, деятельность брокеров-дилеров и бирж; аналог MiFID II по сути регулирования услуг и раскрытия информации.'),
    (145, 'ru', 'З', 'Закон о товарных биржах 1936 г.', 'Commodity Exchange Act (CEA) of 1936', 'Закон, регулирующий торговлю деривативами, фьючерсами и свопами под надзором CFTC — функциональный аналог MiFIR (регулирование торгов и клиринга).'),
    (12, 'ru', 'З', 'Заявка брокера / торговое поручение', 'Order Ticket', 'сообщение распорядительного характера на заключение сделок, подаваемое Брокером (в качестве участника торгов) Организатору торгов в порядке и на условиях, установленных Правилами торгов, в целях исполнения Поручения Клиента.'),

    (234, 'ru', 'И', 'Идентификация', 'Identification', 'Процедура получения и фиксации идентификационных данных Клиента, его представителя и/или бенефициарного владельца в соответствии с требованиями AML/CTF- законодательства.'),
    (137, 'ru', 'И', 'Инвестиционная деятельность', 'Investment Activities', 'Комплекс действий компании в рамках лицензии, включая операции за свой счёт, хранение активов и валютные операции.'),
    (148, 'ru', 'И', 'Инвестиционная рекомендация', 'Investment Advice', 'Персональная рекомендация клиенту по приобретению, продаже или удержанию финансовых инструментов.'),
    (16, 'ru', 'И', 'Инвестиционное консультирование', 'Investment Advisory Services', 'услуга Брокера по предоставлению Клиенту индивидуальных инвестиционных рекомендаций в соответствии с Договором и Приложением № 12 к Регламенту, а также иными внутренними документами Брокера и законодательством Грузии.'),
    (152, 'ru', 'И', 'Инвестиционные исследования и финансовый анализ', 'Investment Research / Financial Analysis', 'Аналитическая деятельность, направленная на предоставление информации и прогнозов по финансовым инструментам и рынкам.'),
    (136, 'ru', 'И', 'Инвестиционные услуги', 'Investment Services', 'Деятельность, лицензированная компанией: приём и исполнение поручений, доверительное управление, консультирование и др.'),
    (15, 'ru', 'И', 'Индивидуальная инвестиционная рекомендация', 'Personalized Investment Advice', 'адресованная конкретному Клиенту информация о ценных бумагах, производных финансовых инструментах, валюте и/или сделках с ними, подготовленная с учётом целей, опыта, финансового положения и отношения Клиента к риску, отвечающая требованиям законодательства Грузии, нормативных актов НБГ и внутренних документов Брокера, регламентирующих деятельность по инвестиционному консультированию.'),
    (176, 'ru', 'И', 'Индикатор спреда', 'Spread Indicator', 'Отклонение текущего спреда от среднестатистического спреда'),
    (189, 'ru', 'И', 'Индикатор целостности данных', 'Data Integrity Indicator', 'Показатель корректности и полноты данных'),
    (17, 'ru', 'И', 'Иностранная валюта', 'Foreign Currency', 'официальная денежная единица соответствующей страны или группы стран (включая евро), отличная от грузинского лари.'),
    (18, 'ru', 'И', 'Иностранная ценная бумага', 'Foreign Security', 'финансовый инструмент, признаваемый ценной бумагой в соответствии с законодательством соответствующей иностранной юрисдикции и обращающийся на иностранных организованных и/или неорганизованных рынках, учёт прав по которому осуществляется у иностранного депозитария, кастодиана, клиринговой организации или иного профессионального участника, деятельность которого регулируется компетентным органом его юрисдикции.'),
    (133, 'ru', 'И', 'Информированный инвестор', 'Informed Investor (Accredited Investor)', 'лицо, являющееся таковым согласно Приказу Президента НБГ № 223/04 от 16 декабря 2020г. «Об утверждении порядка признания лица Информированным инвестором», согласно Порядку принятия решений о признании лиц Информированными инвесторами Rioni Capital LLC, размещённым на Сайте Брокера и в соответствии с Политикой категоризации клиентов брокерской компании "Rioni Capital"'),
    (214, 'ru', 'И', 'Инфраструктурная организация', 'Infrastructure institution', 'Вышестоящий брокер, кастодиан, центральный депозитарий, центральный контрагент, клиринговая организация и иные инфраструктурные организации финансового рынка.'),
    (139, 'ru', 'И', 'Исполнение поручений от имени клиентов', 'Execution of Orders on Behalf of Clients', 'Совершение сделок брокером по поручению клиента с финансовыми инструментами.'),
    (62, 'ru', 'И', 'Исполненная сделка (трейд)', 'Trade Execution / Filled Order', 'Полностью или частично исполненное поручение клиента, имеющее уникальный номер в системе брокера.'),
    (21, 'ru', 'И', 'Итоговое закрытие операционного дня (Итоговое закрытие дня)', 'Daily Reconciliation', 'осуществление Брокером во внутреннем учёте операций и проводок по фиксации в Портфеле Активов Клиента, его прав и Обязательств по состоянию на 14:00:00 (GET) рабочего дня, следующего за отчётным календарным днём.'),
    (215, 'ru', 'И', 'ИТС', 'Trading Platform', 'информационно-торговая система удалённого доступа, предоставляемая Клиенту Брокером для передачи Сообщений и Поручений в электронной форме через сеть Интернет. Перечень торговых систем и программного обеспечения, используемых Брокером, может быть расширен и уточняется на Сайте Брокера и/или в Приложениях к Договору.'),
    (163, 'ru', 'К', 'Капитал', 'Equity', 'Собственный капитал клиента. Денежные средства, ценные бумаги Клиента, находящиеся на Брокерском счёте, а также денежные средства и ценные бумаги Клиента, которые должны поступить на Брокерский счет в результате расчётов по сделкам, заключённым Брокером в интересах Клиента [из Регламента]'),
    (149, 'ru', 'К', 'Кастодиальные (депозитарные) услуги', 'Custody Services', 'Хранение и администрирование финансовых инструментов, включая расчёты, отчётность и корпоративные действия.'),
    (22, 'ru', 'К', 'Категория риска клиента', 'Client Risk Classification', 'категория, характеризующая максимально допустимый уровень риска для Клиента в системе управления рисками Брокера и определяемая Брокером на основании Анкеты и иных сведений о Клиенте в порядке, установленном Договором и внутренними документами Брокера.'),
    (135, 'ru', 'К', 'Квалифицированный контрагент', 'Eligible Counterparty', 'Крупный и опытный участник рынка, совершающий значительные торговые операции (финансовые учреждения, фонды и т.д.).'),
    (216, 'ru', 'К', 'Клиент', 'Client', 'Клиент Брокера - физическое или юридическое лицо, которое имеет договорные отношения с Брокером и обращается к Брокеру с целью совершения сделок с Финансовыми инструментами. Клиент брокера делегирует Брокеру полномочия на совершение сделок с Финансовыми инструментами, предоставляя необходимые для этого ресурсы и принимая на себя сопутствующие риски.'),
    (23, 'ru', 'К', 'Клиринговая организация', 'Clearing House', 'организация, имеющая право осуществлять клиринговую деятельность на основании лицензии или иного разрешения, выданного компетентным органом согласно законодательству Грузии или соответствующей иностранной юрисдикции, а также иностранная организация, осуществляющая деятельность, аналогичную клирингу.'),
    (72, 'ru', 'К', 'Клиринговая сессия', 'Clearing Session', 'Период времени, в течение которого клиринговая организация производит расчёты по открытым позициям, пересчитывает маржу и фиксирует обязательства сторон.'),
    (85, 'ru', 'К', 'Клиринговый участник / член клиринга', 'Clearing Member', 'Участник клиринговой организации, имеющий право проводить расчёты и нести ответственность за позиции клиентов.'),
    (105, 'ru', 'К', 'Компенсационная сумма', 'Compensation Sum', 'Денежная сумма или рыночная стоимость ценных бумаг, подлежащая уплате клиентом в связи с исполнением маржинальных сделок.'),
    (24, 'ru', 'К', 'Конверсионная (спот) сделка', 'Spot FX Transaction', 'Сделка купли-продажи иностранной валюты на организованных валютных рынках.'),
    (25, 'ru', 'К', 'Конвертация валюты', 'Currency Conversion', 'внебиржевая конвертация денежных средств в безналичной форме, то есть обмен исходной валюты Клиента на целевую валюту по согласованному курсу, в том числе в целях замены валюты Обязательства. В Поручении (в том числе Условном поручении) на Конвертацию в целях замены обязательств под исходной валютой понимается валюта, на которую меняется текущая валюта Обязательства; под целевой валютой – валюта, в которой выражено Обязательство на момент подачи такого Поручения (Условного поручения).'),
    (236, 'ru', 'К', 'Конфиденциальная информация', 'Confidential information', 'Любая информация, полученная в рамках AML/CTF-процедур, включая данные о Клиенте, материалы CDD/KYC, результаты мониторинга операций, основания подозрений и факт либо содержание сообщений компетентным органам, подлежащая защите и ограничению раскрытия в соответствии с законом и внутренними документами.'),
    (109, 'ru', 'К', 'Короткая позиция', 'Short Position', 'Позиция, возникающая при продаже ценных бумаг без покрытия (ожидание снижения цены).'),
    (125, 'ru', 'К', 'Корпоративные действия', 'Corporate Actions', 'События, влияющие на ценные бумаги (дивиденды, сплиты, конвертации и т.п.).'),
    (96, 'ru', 'К', 'Коэффициент достаточности капитала (CAR)', 'Capital Adequacy Ratio (CAR)', 'Показатель соотношения чистой стоимости активов к сумме маржинальных требований и немаржируемых активов: CAR = 100% × NAV / (AIM + NMI).'),
    (178, 'ru', 'К', 'Коэффициент ликвидности', 'Quick Ratio', 'Покрытие обязательств ликвидными активами.'),
    (74, 'ru', 'К', 'Кредитное плечо', 'Leverage', 'Соотношение между объёмом открытой позиции и собственными средствами клиента, используемое для увеличения потенциальной доходности (и риска).'),
    (150, 'ru', 'К', 'Кредитование или займ в отношении финансовых инструментов', 'Lending / Credit in respect of Financial Instruments', 'Предоставление клиенту кредита или займа для операций с финансовыми инструментами, при участии компании в сделке.'),
    (213, 'ru', 'Л', 'Ликвидационная маржа', 'Margin Close-Out Level/Liquidation Leve, Close-Out', 'Уровень обеспечения, при достижении которого Брокер начинает принудительное закрытие позиции Клиента'),
    (162, 'ru', 'Л', 'Лимиты риска', 'Exposure Limits', 'Максимально допустимый риск по инструменту / Портфелю'),
    (203, 'ru', 'Л', 'Лимит концентрации', 'Concentration Limit', 'Лимит на один инструмент/одного контрагента'),
    (205, 'ru', 'Л', 'Лимит сектора', 'Sector Exposure Limit', 'Максимальный лимит на одну отрасль.'),
    (206, 'ru', 'Л', 'Лимит страны', 'Country Exposure Limit', 'Максимальный лимит на одну страну.'),
    (204, 'ru', 'Л', 'Лимит эмитента', 'Issuer Concentration Limit', 'Максимальный лимит на одного эмитента.'),
    (155, 'ru', 'Л', 'Лицензия на инвестиционную деятельность', 'Investment Services License', 'Разрешение, выдаваемое регулятором (НБГ/ЕС), на предоставление инвестиционных и сопутствующих услуг.'),
    (28, 'ru', 'Л', 'Личный кабинет клиента', 'Client Portal', 'используемая Брокером и Клиентом авторизованная организационно-техническая система дистанционного обслуживания (программное обеспечение), предоставляющая доступ к услугам Брокера, счетам и операциям Клиента через сеть Интернет. Личный кабинет позволяет заключать и расторгать Договоры, получать и предоставлять услуги, обмениваться Электронными документами и Сообщениями. Правообладателем Личного кабинета является Брокер. Доступ предоставляется Клиенту посредством web-сервиса (в том числе по ссылке, размещённой на Сайте Брокера) и/или мобильного приложения. Личный кабинет предоставляется Клиенту в соответствии с Соглашением об использовании программного обеспечения «Личный кабинет» и дистанционном обслуживании клиентов.'),
    (126, 'ru', 'Л', 'Лок-ап период', 'Lock-up Period', 'Установленный эмитентом срок (обычно 90 дней и более), в течение которого акции нельзя продать после размещения.'),
    (202, 'ru', 'М', 'Максимальное плечо', 'Maximum Leverage', 'Предельное кредитное плечо.'),
    (102, 'ru', 'М', 'Маржинальная сделка', 'Margin Transaction', 'сделка, совершаемая Клиентом с применением кредитного плеча, предоставляемого Брокером (маржинального займа).'),
    (101, 'ru', 'М', 'Маржинальные требования', 'Margin Requirements', 'Сумма обеспечения, требуемая компанией от клиента для открытия и поддержания маржинальной позиции.'),
    (100, 'ru', 'М', 'Маржинальный займ', 'Margin Loan', 'Денежные средства или ценные бумаги, предоставленные компанией клиенту для исполнения маржинальных сделок.'),
    (99, 'ru', 'М', 'Маржин-колл', 'Margin Call', 'Уведомление брокера клиенту о необходимости пополнить счёт или закрыть позиции для восстановления требуемого уровня CAR.'),
    (98, 'ru', 'М', 'Маржируемые активы', 'Marginable Assets', 'Активы клиента, которые могут быть использованы как обеспечение по маржинальным сделкам.'),

    (217, 'ru', 'М', 'Международная ассоциация ISLA (International Securities Lending Association)', 'ISLA', 'международная ассоциация, устанавливающая стандарты и лучшие практики для рынка займов ценных бумаг, включая правила возврата бумаг, компенсации доходов, управление коллатералом и операционное взаимодействие участников.'),
    (90, 'ru', 'М', 'Месяц поставки', 'Delivery Month', 'Календарный месяц, в котором производится исполнение или поставка по фьючерсному контракту.'),
    (92, 'ru', 'М', 'Множитель контракта', 'Contract Multiplier', 'Коэффициент, используемый для определения полной стоимости фьючерсного или опционного контракта (цена × множитель).'),
    (218, 'ru', 'М', 'Модуль Онбординг', 'Onboarding System', 'используемая Брокером и Клиентом авторизованная организационно-техническая система дистанционного обслуживания (программное обеспечение), предназначенная для обеспечения процедуры онбординга Клиента: удаленной идентификации Клиента, обмена документами, заключения Брокерского договора, открытия Брокерского счета. Доступ предоставляется Клиенту посредством web-сервиса и/или мобильного приложения.'),
    (174, 'ru', 'Н', 'Нарушение SLA', 'Counterparty SLA Breach Indicator', 'Нарушение SLA провайдером услуг'),
    (29, 'ru', 'Н', 'Национальный банк Грузии', 'National Bank of Georgia (NBG)', 'центральный банк Грузии, осуществляющий надзор и регулирование деятельности финансовых институтов, включая брокерские компании, в соответствии с законодательством Грузии.'),
    (166, 'ru', 'Н', 'Начальная маржа', 'Initial Margin (IM)', 'Минимальное обеспечение для открытия позиции. (В Регламенте: необходимый уровень обеспечения для открытия позиции)'),
    (70, 'ru', 'Н', 'Начальная маржа / гарантийное обеспечение', 'Initial Margin / Performance Bond', 'параметр системы управления рисками Брокера, определяемый Клиринговой организацией и (или) на основании требований Клиринговой организации к размеру индивидуального клирингового обеспечения по Портфелю Клиента. Значение Начального гарантийного обеспечения, отображаемое в программном обеспечении Клиента, может отличаться от величины, рассчитанной Клиринговой организацией; Клиент обязан самостоятельно контролировать размер Начального гарантийного обеспечения.'),
    (123, 'ru', 'Н', 'Невыставленные ордера / административные поручения', 'Non-trading Orders', 'Заявки, не связанные напрямую с торговыми операциями (например, перевод, отчётность).'),
    (97, 'ru', 'Н', 'Немаржируемые активы', 'Non-marginable Assets (NMI)', 'Активы клиента, не принимаемые в качестве обеспечения по маржинальным операциям.'),
    (233, 'ru', 'Н', 'Необычная транзакция', 'Unusual transaction', 'Сделка или операция, которая по своему объёму, частоте, структуре, экономическому смыслу или несоответствию профилю Клиента является нетипичной и требует дополнительного анализа в целях AML/CTF; необычная сделка может, но не обязательно должна быть признана подозрительной.'),
    (219, 'ru', 'Н', 'Непокрытая позиция', 'Uncovered position', 'отрицательное значение Плановой позиции Клиента, сформированное по Портфелю в разрезе определённого вида Имущества; размер Непокрытой позиции увеличивается Брокером на сумму Обязательств Клиента.'),
    (113, 'ru', 'Н', 'Нестандартный отчёт', 'Non-standard Report', 'Индивидуальный отчёт по счёту, формируемый по запросу (аудит, налоговые органы, суд и т.п.).'),
    (84, 'ru', 'Н', 'Неттинг / взаимозачёт', 'Netting', 'Процесс зачёта встречных обязательств между сторонами для снижения суммарного объёма расчётов и рисков.'),
    (179, 'ru', 'Н', 'Норматив краткосрочной ликвидности', 'Liquidity Coverage Ratio', 'Отношение ликвидных активов к обязательствам.'),
    (87, 'ru', 'О', 'Обеспечение / залог', 'Collateral', 'Активы (деньги, ценные бумаги), предоставляемые в обеспечение обязательств клиента перед брокером или клирингом.'),
    (238, 'ru', 'О', 'Обоснованное подозрение', 'Reasonable assumption', 'Вывод или предположение, основанное на фактах, документах, поведенческих признаках, транзакционных моделях или иных объективных данных, достаточное для целей AML/CTF-оценки, начала дополнительного анализа и/или принятия решения о дальнейшем реагировании.'),
    (31, 'ru', 'О', 'Обязательства клиента', 'Customer Liabilities', 'Все обязательства клиента перед брокером по договорам и операциям, включая оплату услуг и расходов.'),
    (104, 'ru', 'О', 'Обязательства / задолженность клиента', 'Client’s Obligations / Indebtedness', 'Совокупность долговых обязательств клиента перед компанией, включая комиссии, проценты, возврат займов и прочие платежи.'),
    (207, 'ru', 'О', 'Ограничение ликвидности', 'Liquidity Constraint', 'Ограничение позиций по ликвидности.'),
    (32, 'ru', 'О', 'Организатор торгов (биржа, платформа)', 'Exchange / ATS', 'юридическое лицо, в том числе иностранное (биржа, торговая площадка, брокер, банк), обеспечивающее функционирование организованного рынка ценных бумаг, валюты, производных финансовых инструментов и иных Инструментов в соответствии с законодательством соответствующей юрисдикции и собственными Правилами торгов.'),
    (33, 'ru', 'О', 'Основной мобильный телефон', 'Primary Contact Number', 'Основной мобильный номер клиента, указанный в анкете и предоставленный оператором связи.'),
    (225, 'ru', 'О', 'Ответственное лицо', 'Responsible person', 'Лицо или организация, на которую в соответствии с законодательством Грузии в сфере AML/CTF возложены обязанности по предотвращению, выявлению и контролю рисков отмывания денег и финансирования терроризма, включая выполнение установленных процедур и требований (в том числе финансовые институты, такие как брокерская компания).'),
    (239, 'ru', 'О', 'Ответственный сотрудник', 'Responsible employee', 'Сотрудник Брокера, назначенный для выполнения функций по AML/CTF-контролю, включая идентификацию и проверку Клиентов, мониторинг операций, эскалацию подозрительных случаев и взаимодействие с компетентными органами в соответствии с законодательством и внутренними политиками.'),
    (30, 'ru', 'О', 'Открытая позиция', 'Open Position', 'Незакрытая сделка по покупке или продаже актива, сохраняющая потенциальную прибыль или убыток до момента закрытия.'),
    (220, 'ru', 'О', 'Открытая срочная позиция', 'Open Contract', 'количество открытых (заключенных) срочных (фьючерсных или опционных) контрактов в Портфеле Клиента, не реализованных в данный момент времени, т. е. ожидающих завершения расчетов либо истечения контракта.'),
    (77, 'ru', 'О', 'Открытый интерес', 'Open Interest', 'Общее количество действующих (не закрытых и не исполненных) контрактов по конкретному фьючерсу или опциону.'),
    (229, 'ru', 'О', 'Отмывание денег', 'Money laundering', 'Любые действия или операции, направленные на сокрытие или маскировку незаконного происхождения имущества или доходов, полученных преступным путём, либо на придание им видимости законного происхождения, в значении, установленном AML/CTF-законодательством Грузии.'),
    (34, 'ru', 'О', 'Офис брокера', 'Principal Office', 'Основное место нахождения брокера и его подразделений, указанных на сайте компании.'),
    (35, 'ru', 'О', 'Официальный обменный курс', 'Official Exchange Rate', 'Курс валют, установленный и опубликованный Национальным банком Грузии (НБГ).'),
    (175, 'ru', 'О', 'Оценка ликвидности', 'Liquidity Score', 'Показатель ликвидности инструмента.'),
    (172, 'ru', 'О', 'Оценка надёжности контрагента', 'Counterparty Reliability Score', 'Оценка финансовой и технологической/операционной (если применимо) устойчивости контрагента'),
    (36, 'ru', 'П', 'Партнёр (агент по привлечению)', 'Referral Partner', 'юридическое лицо, с которым Брокер заключил договор возмездного оказания услуг по поиску и привлечению потенциальных клиентов, а также по организации документооборота между Брокером и Клиентом, в том числе посредством специального сайта (web-интерфейса) в сети Интернет.'),
    (197, 'ru', 'П', 'Первичная маркет-дата', 'Primary Market Data', 'Информация о ценах от бирж'),
    (127, 'ru', 'П', 'Первичное публичное размещение (IPO)', 'Initial Public Offering (IPO)', 'Размещение акций компании на бирже с целью привлечения капитала.'),
    (120, 'ru', 'П', 'Переводы DWAC / DRS', 'DWAC / DRS Transfers', 'Операции прямого перевода акций через депозитарий DTCC без физического сертификата.'),
    (38, 'ru', 'П', 'Планируемая (расчётная) позиция', 'Expected Exposure', 'Величина, отражающая потенциальное воздействие рыночных изменений на активы клиента по требованиям НБГ.'),
    (89, 'ru', 'П', 'Поддерживающая маржа', 'Maintenance Margin', 'Минимальный уровень маржи, который клиент обязан поддерживать для удержания открытых позиций.'),
    (167, 'ru', 'П', 'Поддерживающая маржа', 'Maintenance Margin (MM)', 'Минимальное обеспечение для удержания позиций.'),
    (240, 'ru', 'П', 'Подозрительная зона', 'Suspicious zone', 'Корпоративный термин (не является обязательным легальным определением): географическая зона, юрисдикция, сегмент клиентов, вид деятельности или операционный канал с повышенным AML/CTF-риском, определённый внутренней оценкой рисков Брокера и/или сообщениями компетентных органов, в отношении которого применяются усиленные меры контроля и мониторинга.'),
    (232, 'ru', 'П', 'Подозрительная транзакция', 'Suspicious transaction', 'Сделка, операция либо попытка её совершения, в отношении которой имеются обоснованные основания полагать, что она может быть связана с отмыванием денег, финансированием терроризма, обходом санкций или иными незаконными целями и, соответственно, подлежит анализу и, при необходимости, сообщению в компетентные органы.'),
    (237, 'ru', 'П', 'Политически значимый человек', 'Politically Exposed Person (PEP)', 'Физическое лицо, которому в настоящее время или в прошлом были поручены значимые публичные функции, а также члены его семьи и лица, тесно с ним связанные, в значении, установленном AML/CTF-законодательством и требованиями регулятора.'),
    (39, 'ru', 'П', 'Портфель Клиента', 'Client Portfolio', 'структурная единица группировки Субсчетов Клиента в системе внутреннего учёта Брокера в рамках Договора, в разрезе которой Брокер осуществляет контроль рисков Клиента и анализ его операций.'),
    (40, 'ru', 'П', 'Поручение клиента / распоряжение', 'Customer Order / Client Instruction', 'Сообщение распорядительного характера, поданное Клиентом Брокеру в целях заключения сделки и/или осуществления операции в интересах Клиента.'),
    (42, 'ru', 'П', 'Поручение по лимитированной цене (Лимитный ордер)', 'Limit Order', 'Поручение на заключение сделки по цене, указанной в Поручении, или по более выгодной для Клиента цене.'),
    (41, 'ru', 'П', 'Поручение по рыночной цене', 'Market Order', 'Поручение на заключение сделки по цене, доступной для Брокера на соответствующих торгах на момент исполнения Поручения (без указания лимита цены). Организатор торгов может устанавливать предельный размер отклонения цен при исполнении таких Поручений; информацию об этом Клиент может получить на официальном сайте соответствующего Организатора торгов.'),
    (107, 'ru', 'П', 'Пояснительная запись', 'Explanatory Note', 'Комментарий к расчётам расходов, включая учёт дивидендов по бумагам, находившимся в обязательствах клиента на дату фиксации.'),
    (43, 'ru', 'П', 'Правила торгов', 'Exchange Rules', 'правила, регламенты, инструкции, процедуры, нормативные документы или требования Организатора торгов, обязательные или рекомендуемые для исполнения всеми участниками торгов на соответствующей Торговой площадке.'),
    (154, 'ru', 'П', 'Предложение инвестиционных продуктов', 'Offering of Investment Products', 'Продажа клиентам финансовых инструментов, соответствующих их профилю риска и инвестиционным целям.'),
    (79, 'ru', 'П', 'Премия опциона', 'Option Premium', 'Цена, уплачиваемая покупателем опциона продавцу за право (но не обязанность) купить или продать базовый актив по установленной цене.'),

    (138, 'ru', 'П', 'Приём и передача поручений', 'Reception and Transmission of Orders', 'Услуга по получению от клиента распоряжений и их передаче третьим лицам для исполнения.'),
    (235, 'ru', 'П', 'Проверка/Верификация', 'Verification', 'Проверка достоверности идентификационных данных Клиента, его представителя и/или бенефициарного владельца на основании документов, сведений или надёжных источников информации в порядке, установленном AML/CTF- требованиями.'),
    (37, 'ru', 'П', 'Программное обеспечение для Клиента (ПО)', 'Client Application Software', 'программы для электронно-вычислительных машин, предоставляемые Клиенту Брокером и (или) используемые Клиентом в соответствии с условиями Договора и соглашений Клиента с третьими лицами, предназначенные для обмена Сообщениями, подачи Поручений и доступа к услугам Брокера.'),
    (221, 'ru', 'П', 'Программное обеспечение для Клиента (ПО)', 'Client software', 'программы для электронно-вычислительных машин, предоставляемые Клиенту Брокером и (или) используемые Клиентом в соответствии с условиями Договора и соглашений Клиента с третьими лицами, предназначенные для обмена Сообщениями, подачи Поручений и доступа к услугам Брокера.'),
    (222, 'ru', 'П', 'Производный финансовый инструмент (ПФИ, срочный контракт, дериватив)', 'Derivative', 'это договор (контракт), по которому стороны получают право или обязуются выполнить некоторые действия в отношении базового актива.'),
    (134, 'ru', 'П', 'Профессиональный клиент', 'Professional Client', 'Клиент, обладающий достаточными знаниями, опытом и активами для понимания рисков и получающий ограниченную защиту MiFID II.'),
    (108, 'ru', 'П', 'Проценты', 'Interest', 'Сумма, начисляемая за использование заёмных средств и/или бумаг в рамках маржинальных сделок.'),
    (44, 'ru', 'Р', 'Рабочий день', 'Business Day', 'календарный день, за исключением официально установленных законодательством Грузии выходных и праздничных дней, а также перенесённых выходных дней, в который Брокер осуществляет деятельность в режиме с 10:00 до 19:00 по грузинскому времени (GET), если иное не установлено Брокером и не доведено до сведения Клиентов посредством Сайта. В дни, являющиеся нерабочими для Брокера, но рабочими для какого-либо Организатора торгов и/или государства валюты расчётов, Брокер вправе по своему усмотрению оказывать отдельные услуги, уведомив Клиентов через Сайт не позднее чем за 2 (два) Рабочих дня.'),
    (106, 'ru', 'Р', 'Расходы', 'Expenses', 'Расходы компании, связанные с маржинальными операциями, не включённые в компенсационную сумму.'),
    (76, 'ru', 'Р', 'Расчётная (клиринговая) цена', 'Settlement Price', 'Цена, устанавливаемая клиринговой организацией для расчёта вариационной маржи и обязательств участников.'),
    (86, 'ru', 'Р', 'Расчётный счёт', 'Settlement Account', 'Специальный счёт, используемый для проведения клиринговых расчётов и взаиморасчётов между участниками.'),
    (143, 'ru', 'Р', 'Регламент (ЕС) №1286/2014 о ключевых информационных документах для комплексных розничных и страховых инвестиционных продуктов (PRIIPs)', 'Regulation (EU) No 1286/2014 on Key Information Documents for Packaged Retail and Insurance-based Investment Products (PRIIPs)', 'Регламент ЕС, устанавливающий требования к содержанию и предоставлению KID-документов (Key Information Documents) для прозрачности и защиты розничных инвесторов.'),
    (142, 'ru', 'Р', 'Регламент (ЕС) №600/2014 о рынках финансовых инструментов (MiFIR)', 'Regulation (EU) No 600/2014 on Markets in Financial Instruments (MiFIR)', 'Регламент ЕС, дополняющий MiFID II; регулирует исполнение торгов, отчётность, прозрачность и доступ к рынкам.'),
    (122, 'ru', 'Р', 'Редомициляция', 'Redomiciliation', 'Перерегистрация юридического лица или фонда в другую юрисдикцию с сохранением структуры владения.'),
    (45, 'ru', 'Р', 'Реестр владельцев ценных бумаг', 'Shareholder Register', 'список лиц (владельцев ценных бумаг), имеющих право на получение доходов по ценным бумагам и иных выплат/распределений, составляемый эмитентом ценных бумаг или иным уполномоченным лицом в соответствии с применимым законодательством.'),
    (171, 'ru', 'Р', 'Риск на контрагента', 'Counterparty Exposure', 'Риск на контрагента'),
    (156, 'ru', 'Р', 'Риск позиции', 'Exposure', 'Общий объём риска по открытой позиции.'),
    (6, 'ru', 'Р', 'Риск-профиль клиента', 'Client Risk Profile', 'Параметры системы управления рисками, применяемые к портфелю клиента.'),
    (132, 'ru', 'Р', 'Розничный клиент', 'Retail Client', 'Клиент, не являющийся профессиональным или квалифицированным контрагентом; получает максимальную регуляторную защиту.'),
    (46, 'ru', 'Р', 'Рынок', 'Market', 'определённое Брокером место заключения сделок с Инструментами определённого вида. В рамках Договора Брокер выделяет, в частности, фондовый рынок, срочный рынок и валютный рынок.'),
    (119, 'ru', 'Р', 'Рыночные данные в реальном времени', 'Real-time Market Data', 'Поток котировок и информации о торгах, предоставляемый по подписке.'),
    (48, 'ru', 'С', 'Санкционные ограничения', 'Sanctions Restrictions', 'любые меры ограничительного характера (включая экономические, финансовые, торговые санкции и иные ограничения), принятые или введённые: • государственными органами Грузии; • органами иностранных государств, союзов государств, международными организациями (включая, но не ограничиваясь, United Nations Organisation, United States Department of the Treasury, Council of the European Union, HM Treasury, Office of Foreign Assets Control); в отношении государств, лиц, валют, финансовых инструментов или операций и запрещающие прямо или опосредованно: i. осуществлять покупку, продажу, инвестирование; ii. осуществлять обслуживание, финансовое посредничество, участие в первичном размещении; iii. совершать и/или исполнять отдельные или все виды сделок с финансовыми инструментами; iv. осуществлять платежи и/или операции, необходимые для исполнения Поручений Клиента или обязательств по сделкам в интересах Клиента. К Санкционным ограничениям, в частности, относится включение указанных лиц в санкционный список Министерства финансов США «SDN List», а также в иные официальные санкционные списки.'),
    (116, 'ru', 'С', 'Свопы и структурные ноты', 'Swaps and Structured Notes', 'OTC-деривативы, заключаемые напрямую между участниками, вне биржи.'),
    (231, 'ru', 'С', 'Связанные транзакции', 'Related Transactions', 'Несколько взаимосвязанных сделок или операций, объединённых общим экономическим смыслом, целью, участниками, источником или назначением средств либо иными признаками, которые для целей AML/CTF подлежат рассмотрению в совокупности.'),
    (140, 'ru', 'С', 'Сделки за собственный счёт', 'Dealing on Own Account', 'Торговые операции, совершаемые компанией за счёт собственных средств, а не клиента.'),
    (186, 'ru', 'С', 'Системные сбои', 'System Outages', 'Недоступность критичных ИТ-систем.'),
    (94, 'ru', 'С', 'Скорректированная начальная маржа', 'Adjusted Initial Margin (AIM)', 'Совокупная сумма маржинальных требований по всем открытым позициям и ордерам клиента.'),
    (223, 'ru', 'С', 'Сообщение', 'Notification', 'любое сообщение распорядительного или информационного характера, направляемое Брокером Клиенту или Клиентом Брокеру в процессе исполнения Договора, в том числе посредством Личного кабинета, ИТС, электронной почты, Чата и иных согласованных каналов связи.'),
    (153, 'ru', 'С', 'Сопутствующие услуги', 'Ancillary Services', 'Дополнительные услуги, предоставляемые вместе с инвестиционными — отчётность, хранение, клиринг, консалтинг и др.'),
    (52, 'ru', 'С', 'Специализированный депозитарий', 'Qualified Custodian', 'организация, осуществляющая деятельность специализированного депозитария инвестиционных фондов, пенсионных схем и/или иных коллективных инвестиционных институтов на основании лицензии или иного разрешения, выданного компетентным органом в соответствии с законодательством Грузии или соответствующей иностранной юрисдикции.'),
    (51, 'ru', 'С', 'Спецификация контракта / сделки', 'Contract Specification', 'стандартизированные условия производного финансового инструмента или сделки, установленные Правилами торгов и/или Договором (включая вид Инструмента, базовый актив, размер лота, срок обращения, порядок расчётов и иные параметры).'),
    (73, 'ru', 'С', 'Спецификация фьючерсного контракта', 'Futures Contract Specification', 'Документ, устанавливающий стандартные условия фьючерсного контракта: размер лота, базовый актив, дата экспирации, тип расчётов и шаг цены.'),
    (200, 'ru', 'С', 'Справочные цены', 'Reference Prices', 'Цены для оценки активов.'),
    (53, 'ru', 'С', 'Стандартный лот', 'Round Lot / Standard Lot', 'Минимальное количество инструмента, определённое торговой площадкой для заключения сделок.'),
    (3, 'ru', 'С', 'Стандарт защиты прав инвесторов', 'Fiduciary Standard', 'Базовый принцип защиты прав и интересов инвесторов, определённый законодательством Грузии.'),
    (54, 'ru', 'С', 'Стоимость портфеля', 'Portfolio Value', 'совокупность Плановых позиций Клиента одного Портфеля, выраженная в грузинских лари (либо в иностранной валюте, если это предусмотрено Договором). Стоимость портфеля, отображаемая в программном обеспеченииИТС, используемом Клиентом для обмена Сообщениями с Брокером, может отличаться от стоимости, рассчитанной Брокером и раскрытой в Личном кабинете; Клиент обязан самостоятельно контролировать Стоимость любого своего Портфеля.'),
    (55, 'ru', 'С', 'Стоп-поручение/Стоп-ордер / Стоп-лимитный ордер', 'Stop Order / Stop-Limit Order', 'Поручение по лимитированной или рыночной цене на биржевую сделку с отлагательными условиями, предусмотренными функциональными возможностями ПО, исполнение которого становится обязательным для Брокера после наступления указанных в Поручении условий выставления заявок и/или заключения сделок.'),
    (160, 'ru', 'С', 'Стресс-убыток', 'Stress-Loss', 'Убыток портфеля при стрессовых изменениях рынка.'),
    (201, 'ru', 'С', 'Стресс-цены', 'Stress Prices', 'Цены для стресс-тестирования.'),
    (117, 'ru', 'С', 'Структурированные продукты', 'Structured Products', 'Комплексные финансовые инструменты, сочетающие ценные бумаги и деривативы.'),
    (56, 'ru', 'С', 'Субброкер / Интродьюсинг- брокер', 'Sub-Broker / Introducing Broker', 'Клиент Брокера, являющийся профессиональным участником рынка ценных бумаг и осуществляющий брокерскую деятельность в интересах и по поручению своих клиентов на основании лицензии или иного разрешения регулятора страны регистрации такого Клиента.'),
    (27, 'ru', 'С', 'Субсчет Клиента', 'Sub-Account', 'структурная единица внутреннего учёта Брокера, являющаяся составной частью Портфеля Клиента и предназначенная для учёта количества Имущества и Обязательств Клиента посредством отражения сделок и операций с ценными бумагами, деривативами, драгоценными металлами и денежными средствами Клиента. В рамках одного Портфеля Клиента открывается не менее одного Субсчёта; количество и структура Лицевых счетов определяются Клиентом и/или Брокером в соответствии с Договором.'),
    (118, 'ru', 'С', 'Счёт Типа E / ER', 'E / ER Type Account', 'Классификация клиентских счетов в американских брокерах, различающая уровень маржинальных прав и ограничений.'),
    (57, 'ru', 'Т', 'Тарифный план', 'Fee Schedule', 'определённая Брокером стандартная форма коммерческого предложения, в которой указываются перечень предоставляемых услуг и порядок определения их стоимости. Перечень Тарифных планов и условия их применения содержатся в Приложениях № 2 и 2а к Договору.'),
    (71, 'ru', 'Т', 'Текущая вариационная маржа', 'Mark-to-Market Margin', 'Вариационная маржа, рассчитываемая Клиринговой организацией по формуле расчёта вариационной маржи в ходе клирингового сеанса с использованием текущей расчётной цены i-го срочного контракта. Суммарная Текущая вариационная маржа в i-й валюте формирует обязательства/требования Клиента и включается в Плановую позицию по соответствующей валюте. Клиент обязан самостоятельно контролировать Текущую вариационную маржу.'),
    (81, 'ru', 'Т', 'Тип опциона (Колл / Пут)', 'Option Type (Call / Put)', 'Определяет право на покупку (Call) или продажу (Put) базового актива по фиксированной цене.'),
    (114, 'ru', 'Т', 'Торговая платформа CQG', 'CQG Trading Platform', 'Международная система для торговли фьючерсами и деривативами; брокеры применяют надбавки к её тарифам.'),
    (20, 'ru', 'Т', 'Торговая платформа DevEx', 'DevEx Electronic Trading Platform', 'Электронная торговая система, разработанная Devexperts Solutions для доступа к операциям на финансовых рынках через Интернет.'),
    (60, 'ru', 'Т', 'Торговый день / Сессия', 'Trading Session / Market Day', 'период времени, в течение которого Организаторы торгов проводят торги. Перечень доступных Организаторов торгов и их расписание публикуются на Сайте Брокера.'),
    (58, 'ru', 'Т', 'Торговый код клиента', 'Account ID / Trader Code', 'Уникальный буквенно-цифровой код, присваиваемый брокером для идентификации клиента и его операций.'),

    (59, 'ru', 'Т', 'Торговый сбор («Сбор ТС»)', 'Trading Fee', 'Дополнительное вознаграждение брокера за совершение биржевых сделок по поручению клиента, согласно тарифам.'),
    (230, 'ru', 'Т', 'Транзакции', 'Transactions', 'Любая операция или совокупность действий Клиента или Брокера, связанных с финансовыми инструментами, денежными средствами, валютой или иными активами, включая подачу и исполнение поручений, переводы, конвертацию и расчёты, в целях AML/CTF-контроля.'),
    (169, 'ru', 'Т', 'Триггер выставления маржинального требования', 'Margin Call Trigger', 'Уровень маржи, при котором Клиенту направляется маржинальное требование (требование довнести обеспечение или закрыть позицию в необходимом объеме)'),
    (170, 'ru', 'Т', 'Триггер принудительного закрытия', 'Margin Close-Out Trigger', 'Уровень обеспечения, при достижении которого Брокер начинает принудительное закрытие позиции Клиента'),
    (49, 'ru', 'У', 'Уведомление брокера', 'Broker Notification', 'Любое административное или информационное сообщение, обмениваемое между брокером и клиентом в ходе исполнения договора.'),
    (78, 'ru', 'У', 'Уведомление о поставке', 'Delivery Notice', 'Документ, направляемый участником клиринга при намерении исполнить контракт путём поставки базового актива.'),
    (147, 'ru', 'У', 'Управление инвестиционным портфелем', 'Portfolio Management', 'Деятельность по доверительному управлению активами клиента на основании его инвестиционных целей и стратегии.'),
    (7, 'ru', 'У', 'Управляющий активами / Инвест. советник', 'Investment Adviser', 'Управляющая компания или фонд, управляющий активами или фондами на основании лицензии.'),
    (168, 'ru', 'У', 'Уровень маржи', 'Margin Level', 'Отношение капитала к требуемой марже.'),
    (190, 'ru', 'У', 'Уровень ошибочных ручных операций', 'Error Rate of Manual Operations', 'Частота ошибок персонала при выполнении ручных операций.'),
    (63, 'ru', 'У', 'Условное поручение / Условная заявка / приказ', 'Conditional Order', 'Поручение, содержащееся в тексте Договора, его Приложений или отдельного соглашения между Клиентом и Брокером, исполняемое Брокером только при выполнении указанных в нём условий.'),
    (228, 'ru', 'Ф', 'Финансирование терроризма', 'Financing of terrorism', 'Деятельность или операция, направленная на предоставление, сбор, перевод или использование денежных средств или иного имущества с целью поддержки террористической деятельности, террориста или террористической организации, независимо от законности происхождения таких средств.'),
    (19, 'ru', 'Ф', 'Финансовый инструмент', 'Financial Instrument', 'предмет и основные условия сделки (ценные бумаги, производные финансовые инструменты, валюта и др.), которая может быть заключена Брокером по Поручению Клиента в рамках Договора.'),
    (88, 'ru', 'Ф', 'Фонд дефолтов', 'Default Fund', 'Резервный фонд клиринговой организации, используемый для покрытия убытков в случае неисполнения обязательств участниками.'),
    (131, 'ru', 'Ф', 'Формат отчётности', 'Reporting Format', 'Структура представления брокерских отчётов, используемая для расчётов и аудита.'),
    (83, 'ru', 'Ф', 'Фьючерсная позиция', 'Futures Position', 'Обязательство участника купить (лонг) или продать (шорт) базовый актив по фьючерсному контракту.'),
    (75, 'ru', 'Х', 'Хеджирование', 'Hedging', 'Операция по снижению рыночного риска с помощью встречных сделок или деривативов.'),
    (129, 'ru', 'Х', 'Хранение активов', 'Safekeeping', 'Услуга по безопасному хранению ценных бумаг и активов клиента в депозитарии или у кастодиана.'),
    (64, 'ru', 'Ц', 'Ценные бумаги', 'Securities', 'эмиссионные и неэмиссионные ценные бумаги, включая акции, облигации, инвестиционные паи, иные долевые и долговые инструменты, а также иностранные ценные бумаги, признаваемые таковыми в соответствии с законодательством Грузии и (или) применимым законодательством соответствующих иностранных юрисдикций'),
    (65, 'ru', 'Ц', 'Центральный депозитарий', 'Central Securities Depository', 'депозитарий, которому в соответствии с законодательством Грузии присвоен статус центрального депозитария.'),
    (185, 'ru', 'Ч', 'Частота инцидентов', 'Incident Frequency', 'Количество операционных инцидентов за период.'),
    (66, 'ru', 'Ч', 'Чат', 'Instant Messaging System', 'канал обмена информацией и Сообщениями в режиме реального времени в Программном обеспечении, предоставляемом Брокером Клиенту.'),
    (164, 'ru', 'Ч', 'Чистая ликвидационная стоимость', 'NLV — Net Liquidation Value', 'Ликвидационная стоимость Портфеля'),
    (103, 'ru', 'Ч', 'Чистая стоимость активов', 'Net Asset Value (NAV)', 'Рыночная стоимость активов клиента за вычетом всех обязательств перед компанией.'),
    (161, 'ru', 'Ч', 'Чувствительность к гэпам', 'Gap Sensitivity', 'Чувствительность Портфеля к резким скачкам цены'),
    (184, 'ru', 'Ч', 'Чувствительность к изменению валютного курса', 'FX Sensitivity', 'Реакция Портфеля на изменение валютного курса.'),
    (91, 'ru', 'Ш', 'Шаг цены / минимальный тик', 'Tick Size', 'Наименьшее возможное изменение цены финансового инструмента, установленное спецификацией контракта.'),
    (82, 'ru', 'Э', 'Экспирация опциона', 'Option Expiration', 'Дата окончания действия опциона, после которой контракт теряет силу и перестаёт быть обращаемым.'),
    (67, 'ru', 'Э', 'Электронная подпись (ЭП)', 'E-Signature', 'информация в электронной форме, прикреплённая к иным электронным данным или логически с ними связанная и используемая для идентификации подписанта и подтверждения целостности электронного документа. В рамках настоящего Регламента используется простая электронная подпись в значении, определённом применимым законодательством Грузии и Соглашением об использовании электронной подписи (Приложение № 8 к Регламенту).'),
    (224, 'ru', 'Э', 'Электронный документ', 'Electronic document', 'информация, зафиксированная в электронной форме и содержащая обязательные реквизиты, позволяющие однозначно идентифицировать её содержание, автора и момент формирования. Электронный документ обладает юридической силой, равнозначной бумажному документу, при условии использования установленного способа электронного подтверждения (электронная подпись, SSO- аутентификация, квалифицированные средства идентификации или иные методы, признанные регулятором)'),
    (210, 'ru', 'A–Z', 'CCP (Центральный контрагент)', 'CCP (Central Counterparty)', 'Центральный контрагент — Юридическое лицо, осуществляющее клиринговую деятельность в соответствии с законодательством Грузии или иностранным регулированием и принимающее на себя функцию центрального контрагента по Сделкам Клиентов и Брокера. CCP становится покупателем для каждого продавца и продавцом для каждого покупателя (novation), обеспечивая клиринг, расчёты, управление рисками, маржинальные требования, процедуру закрытия позиций (close-out) и иные функции, предусмотренные его правилами.'),
    (165, 'ru', 'A–Z', 'Exposure at Default (EAD)', 'Exposure at Default (EAD)', 'Риск убытков в случае дефолта'),
    (115, 'ru', 'A–Z', 'FIX-интерфейс', 'FIX Interface', 'Протокол подключения внешних торговых систем и алгоритмов к брокеру; стоимость зависит от скорости и объёма инструментов.'),
    (121, 'ru', 'A–Z', 'FOP-операции (Free of Payment)', 'FOP Transfers', 'Переводы ценных бумаг между брокерами без денежного расчёта (расчёт уже произведён ранее).'),
    (68, 'ru', 'A–Z', 'ID Клиента / Уникальный идентификатор клиента (UCI)', 'Client ID / Unique Client Identifier (UCI)', 'Персональный буквенно-цифровой код, присваиваемый клиенту при регистрации на сайте брокера и неизменный на протяжении отношений.'),
    (2, 'ru', 'A–Z', 'KYC-данные', 'KYC Data', 'Информация о клиенте, его представителях и бенефициарах, предоставляемая брокеру в рамках анкеты и документов.'),
    (192, 'ru', 'A–Z', 'Latency / Задержка', 'Latency', 'Задержка отклика.'),
    (196, 'ru', 'A–Z', 'RPO (Recovery Point Objective)', 'RPO (Recovery Point Objective)', 'Допустимая потеря данных.'),
    (195, 'ru', 'A–Z', 'RTO (Recovery Time Objective)', 'RTO (Recovery Time Objective)', 'Допустимое время восстановления'),
    (191, 'ru', 'A–Z', 'Uptime / Доступность', 'Uptime', 'Процент доступности сервиса.'),
    (159, 'ru', 'A–Z', 'Value-at-Risk (VAR)', 'Value-at-Risk (VaR)', 'Максимальная ожидаемая потеря при заданном доверительном интервале.'),
    (58, 'en', 'A', 'Account ID / Trader Code', 'Account ID / Trader Code', 'A unique alphanumeric code assigned by the Broker to identify the Client and its transactions.'),
    (93, 'en', 'A', 'Additional Fee', 'Additional Fee', 'A fee charged to the Client in the event of violation of the Capital Adequacy Ratio (CAR) in order to cover the Company’s expenses.'),
    (94, 'en', 'A', 'Adjusted Initial Margin (AIM)', 'Adjusted Initial Margin (AIM)', 'The aggregate amount of margin requirements for all open positions and orders of the Client.'),
    (95, 'en', 'A', 'Analytical Value', 'Analytical Value', 'A revalued market or calculated fair value of securities in a margin transaction, taking into account accrued interest.'),
    (153, 'en', 'A', 'Ancillary Services', 'Ancillary Services', 'Additional services provided together with investment services — reporting, custody, clearing, consulting, etc.'),
    (4, 'en', 'B', 'Bank / Custodian Bank', 'Bank / Custodian Bank', 'Any bank in which the Broker has opened bank accounts for the purposes of settlements for Clients’ transactions and/or its own operations.'),
    (26, 'en', 'B', 'Base Currency / Target Currency', 'Base Currency / Target Currency', 'The currency from (into) which conversion is carried out or in which an obligation is denominated.'),
    (226, 'en', 'B', 'Beneficial Owner', 'Beneficial Owner', 'A natural person(s) who ultimately owns or controls the Client and/or on whose behalf a transaction or operation is conducted, including control exercised through an ownership structure or otherwise, directly or indirectly.'),
    (211, 'en', 'B', 'Broker', 'Broker', 'Rioni Capital LLC (the Broker) — a professional participant in the securities market holding a brokerage license of the National Bank of Georgia, acting in the name and at the expense of the Client, or in its own name and at the expense of the Client, when concluding transactions with Financial Instruments for remuneration (commission).'),

    (241, 'en', 'B', 'Broker (Company, Rioni Capital LLC)', 'Broker (Company, Rioni Capital LLC)', 'The brokerage company Rioni Capital LLC, licensed by the National Bank of Georgia to conduct brokerage activities, which, when concluding transactions with financial instruments, acts on behalf and at the expense of the Client or in its own name and at the expense of the Client. With respect to the recording of the Client’s rights to dematerialized securities, the Broker acts as an “account-holding entity” within the meaning of the Law of Georgia “On Ownership of Dematerialized Securities” and ensures the recording of such rights with a depository/custodian.'),
    (49, 'en', 'B', 'Broker Notification', 'Broker Notification', 'Any administrative or informational message exchanged between the Broker and the Client in the course of performance of the Agreement.'),
    (14, 'en', 'B', 'Brokerage Account', 'Brokerage Account', 'A structural unit for grouping information about operations related to movements of the Client’s Property in the Broker’s internal accounting system, used, inter alia, for the purposes of applying the Fee Schedule.'),
    (212, 'en', 'B', 'Brokerage Agreement', 'Brokerage Agreement', 'A brokerage services agreement concluded between Rioni Capital LLC (the Broker) and the Client, regulating the procedure for the Broker’s provision of services in financial markets, opening and maintaining the Client’s Brokerage Account, as well as the rights and obligations of the Parties. All appendices thereto, including these Regulations (Appendix No. 1 to the Brokerage Agreement), constitute an integral part of the Brokerage Agreement.'),
    (47, 'en', 'B', 'Broker’s Website', 'Broker’s Website', 'The official website of the Company (www.rioni-capital.ge), containing information and documents for Clients.'),
    (44, 'en', 'B', 'Business Day', 'Business Day', 'A calendar day, excluding officially established weekends and public holidays under the legislation of Georgia, as well as transferred days off, on which the Broker conducts activities from 10:00 to 19:00 Georgian time (GET), unless otherwise established by the Broker and communicated to Clients via the Website. On days that are non-business days for the Broker but business days for any Trading Organizer and/or the state of the settlement currency, the Broker may, at its discretion, provide certain services, notifying Clients via the Website no later than 2 (two) Business Days in advance.'),
    (227, 'en', 'B', 'Business Relationship', 'Business Relationship', 'A relationship between a reporting entity and a Client established in connection with the provision of services or products which, by their nature, imply a certain duration (including the opening and maintenance of an account).'),
    (96, 'en', 'C', 'Capital Adequacy Ratio (CAR)', 'Capital Adequacy Ratio (CAR)', 'An indicator of the ratio of net asset value to the sum of margin requirements and non-marginable assets: CAR = 100% × NAV / (AIM + NMI).'),
    (111, 'en', 'C', 'Cashless Transaction', 'Cashless Transaction', 'A transaction in which settlements are carried out by transfer without the use of cash funds.'),
    (210, 'en', 'C', 'CCP (Central Counterparty)', 'CCP (Central Counterparty)', 'A central counterparty — a legal entity performing clearing activities in accordance with the legislation of Georgia or foreign regulation and assuming the function of a central counterparty for transactions of Clients and the Broker. The CCP becomes the buyer to every seller and the seller to every buyer (novation), ensuring clearing, settlements, risk management, margin requirements, close-out procedures, and other functions provided for by its rules.'),
    (65, 'en', 'C', 'Central Securities Depository', 'Central Securities Depository', 'A depository that has been granted the status of a central securities depository in accordance with the legislation of Georgia.'),
    (23, 'en', 'C', 'Clearing House', 'Clearing House', 'An organization entitled to perform clearing activities on the basis of a license or other authorization issued by the competent authority under the legislation of Georgia or the relevant foreign jurisdiction, as well as a foreign organization performing activities similar to clearing.'),
    (85, 'en', 'C', 'Clearing Member', 'Clearing Member', 'A participant of a clearing organization entitled to perform settlements and bear responsibility for clients’ positions.'),
    (72, 'en', 'C', 'Clearing Session', 'Clearing Session', 'A period of time during which the Clearing House performs settlements on open positions, recalculates margin, and records the obligations of the parties.'),
    (216, 'en', 'C', 'Client', 'Client', 'A Client of the Broker — a natural or legal person having contractual relations with the Broker and applying to the Broker for the purpose of concluding transactions with Financial Instruments. The Client delegates to the Broker the authority to conclude transactions with Financial Instruments, providing the necessary resources and assuming the associated risks.'),
    (37, 'en', 'C', 'Client Application Software', 'Client Application Software', 'Computer programs provided by the Broker to the Client and/or used by the Client in accordance with the Agreement and the Client’s agreements with third parties, intended for exchanging Notifications, submitting Instructions, and accessing the Broker’s services.'),
    (13, 'en', 'C', 'Client Assets', 'Client Assets', 'The Client’s cash, securities held in the Brokerage Account, precious metals, as well as the Client’s cash, securities, precious metals that are to be credited to the Brokerage Account as a result of settlements under transactions concluded by the Broker in the Client’s interests.'),
    (68, 'en', 'C', 'Client ID / Unique Client Identifier (UCI)', 'Client ID / Unique Client Identifier (UCI)', 'A personal alphanumeric code assigned to the Client upon registration on the Broker’s website and remaining unchanged throughout the relationship.'),
    (28, 'en', 'C', 'Client Portal', 'Client Portal', 'An authorized organizational and technical remote service system (software) used by the Broker and the Client, providing access to the Broker’s services, the Client’s accounts and transactions via the Internet. The Client Portal enables conclusion and termination of Agreements, receipt and provision of services, and exchange of Electronic Documents and Notifications. The right holder of the Client Portal is the Broker. Access is provided to the Client via a web service (including via a link placed on the Broker’s Website) and/or a mobile application. The Client Portal is provided to the Client in accordance with the Software Use Agreement “Client Portal” and remote client service agreement.'),
    (39, 'en', 'C', 'Client Portfolio', 'Client Portfolio', 'A structural unit for grouping the Client’s Sub-Accounts in the Broker’s internal accounting system under the Agreement, within which the Broker performs control of the Client’s risks and analysis of its transactions.'),
    (1, 'en', 'C', 'Client Questionnaire', 'Client Questionnaire', 'A collective term for the Individual Questionnaire and the Legal Entity Questionnaire (forms in Appendix No. 1 to the Agreement).'),
    (22, 'en', 'C', 'Client Risk Classification', 'Client Risk Classification', 'A category characterizing the maximum permissible level of risk for the Client in the Broker’s risk management system and determined by the Broker based on the Questionnaire and other information about the Client in accordance with the procedure established by the Agreement and the Broker’s internal documents.'),
    (6, 'en', 'C', 'Client Risk Profile', 'Client Risk Profile', 'Parameters of the risk management system applied to the Client’s portfolio.'),
    (221, 'en', 'C', 'Client software', 'Client software', 'Software for electronic computing machines provided by the Broker to the Client and/or used by the Client in accordance with the Agreement and the Client’s agreements with third parties, intended for exchanging Messages, submitting Orders, and accessing the Broker’s services.'),
    (112, 'en', 'C', 'Client’s Assets (Confirmed)', 'Client’s Assets (Confirmed)', 'Cash funds and securities of the Client that meet the Company’s requirements and are available as collateral.'),
    (104, 'en', 'C', 'Client’s Obligations / Indebtedness', 'Client’s Obligations / Indebtedness', 'The aggregate of the Client’s debt obligations to the Company, including commissions, interest, loan repayments, and other payments.'),
    (87, 'en', 'C', 'Collateral', 'Collateral', 'Assets (cash, securities) provided as collateral to secure the Client’s obligations to the Broker or the clearing organization.'),
    (145, 'en', 'C', 'Commodity Exchange Act (CEA) of 1936', 'Commodity Exchange Act (CEA) of 1936', 'A law regulating trading in derivatives, futures, and swaps under the supervision of the CFTC; a functional analogue of MiFIR (regulation of trading and clearing).'),
    (105, 'en', 'C', 'Compensation Sum', 'Compensation Sum', 'A monetary amount or market value of securities payable by the Client in connection with execution of margin transactions.'),
    (203, 'en', 'C', 'Concentration Limit', 'Concentration Limit', 'A limit per single instrument / single counterparty.'),
    (63, 'en', 'C', 'Conditional Order', 'Conditional Order', 'An Instruction contained in the text of the Agreement, its Appendices, or a separate agreement between the Client and the Broker, executed by the Broker only upon fulfillment of the conditions specified therein.'),
    (236, 'en', 'C', 'Confidential Information', 'Confidential Information', 'Any information obtained within AML/CTF procedures, including Client data, CDD/KYC materials, results of transaction monitoring, grounds for suspicion, and the fact or content of reports to competent authorities, which is subject to protection and restricted disclosure in accordance with the law and internal documents.'),
    (92, 'en', 'C', 'Contract Multiplier', 'Contract Multiplier', 'A coefficient used to determine the total value of a futures or options contract (price × multiplier).'),
    (51, 'en', 'C', 'Contract Specification', 'Contract Specification', 'Standardized terms of a derivative financial instrument or transaction established by the Trading Rules and/or the Agreement (including the type of Instrument, underlying asset, lot size, term to maturity, settlement procedure and other parameters).'),
    (125, 'en', 'C', 'Corporate Actions', 'Corporate Actions', 'Events affecting securities (dividends, splits, conversions, etc.).'),
    (171, 'en', 'C', 'Counterparty Exposure', 'Counterparty Exposure', 'Counterparty risk.'),
    (172, 'en', 'C', 'Counterparty Reliability Score', 'Counterparty Reliability Score', 'An assessment of the counterparty’s financial and technological/operational resilience (if applicable).'),
    (174, 'en', 'C', 'Counterparty SLA Breach Indicator', 'Counterparty SLA Breach Indicator', 'Breach of SLA by the service provider.'),
    (206, 'en', 'C', 'Country Exposure Limit', 'Country Exposure Limit', 'The maximum limit per single country.'),
    (114, 'en', 'C', 'CQG Trading Platform', 'CQG Trading Platform', 'An international system for trading futures and derivatives; brokers apply mark-ups to its tariffs.'),
    (5, 'en', 'C', 'Currency', 'Currency', 'National or foreign monetary units, including the Georgian lari.'),
    (25, 'en', 'C', 'Currency Conversion', 'Currency Conversion', 'An over-the-counter conversion of cashless funds, i.e., an exchange of the Client’s source currency into the target currency at an agreed rate, including for the purpose of replacing the currency of a Liability. In an Instruction (including a Conditional Instruction) for Conversion for the purpose of replacing liabilities, the source currency means the currency into which the current currency of the Liability is converted; the target currency means the currency in which the Liability is denominated at the time such Instruction (Conditional Instruction) is submitted.'),
    (149, 'en', 'C', 'Custody Services', 'Custody Services', 'Custody and administration of financial instruments, including settlements, reporting, and corporate actions.'),
    (31, 'en', 'C', 'Customer Liabilities', 'Customer Liabilities', 'All obligations of the Client to the Broker under agreements and transactions, including payment for services and expenses.'),
    (40, 'en', 'C', 'Customer Order / Client Instruction', 'Customer Order / Client Instruction', 'An instruction-type message submitted by the Client to the Broker for the purpose of concluding a transaction and/or performing an operation in the Client’s interests.'),
    (21, 'en', 'D', 'Daily Reconciliation', 'Daily Reconciliation', 'The Broker’s recording in internal accounting of operations and entries to fix, in the Client Assets Portfolio, the Client’s rights and Liabilities as of 14:00:00 (GET) on the business day following the reporting calendar day.'),
    (189, 'en', 'D', 'Data Integrity Indicator', 'Data Integrity Indicator', 'An indicator of data accuracy and completeness.'),
    (140, 'en', 'D', 'Dealing on Own Account', 'Dealing on Own Account', 'Trading operations conducted by the Company using its own funds rather than the Client’s funds.'),
    (88, 'en', 'D', 'Default Fund', 'Default Fund', 'A reserve fund of the clearing organization used to cover losses in the event of default by participants.'),
    (90, 'en', 'D', 'Delivery Month', 'Delivery Month', 'The calendar month in which performance or delivery under a futures contract takes place.'),

    (78, 'en', 'D', 'Delivery Notice', 'Delivery Notice', 'A document submitted by a clearing participant when intending to perform a contract through delivery of the underlying asset.'),
    (124, 'en', 'D', 'Dematerialization (DEMAT)', 'Dematerialization (DEMAT)', 'Conversion of securities into book-entry form with record-keeping through a depository.'),
    (222, 'en', 'D', 'Derivative', 'Derivative', 'A derivative financial instrument (DFI, derivative contract, derivative) — a contract under which the parties obtain rights or assume obligations to perform certain actions in respect of an underlying asset.'),
    (20, 'en', 'D', 'DevEx Electronic Trading Platform', 'DevEx Electronic Trading Platform', 'An electronic trading system developed by Devexperts Solutions for access to financial market transactions via the Internet.'),
    (141, 'en', 'D', 'Directive 2014/65/EU on Markets in Financial Instruments (MiFID II)', 'Directive 2014/65/EU on Markets in Financial Instruments (MiFID II)', 'The main EU act establishing requirements for the provision of investment services, client classification, and investor protection.'),
    (194, 'en', 'D', 'Downtime', 'Downtime', 'Period of service/equipment unavailability.'),
    (120, 'en', 'D', 'DWAC / DRS Transfers', 'DWAC / DRS Transfers', 'Operations for the direct transfer of shares through the DTCC depository without a physical certificate.'),
    (118, 'en', 'E', 'E / ER Type Account', 'E / ER Type Account', 'A classification of client accounts at U.S. brokers that differentiates the level of margin rights and restrictions.'),
    (8, 'en', 'E', 'E-Sign (Remote Agreement)', 'E-Sign (Remote Agreement)', 'Execution (acceptance) of the Agreement by sending to the Broker the documents and information required to enter into the Agreement and its Appendices, in electronic form (including using a simple electronic signature), via a dedicated section of the Website, the Client Portal, or the Partner’s web interface using special technical means, in accordance with applicable civil legislation of Georgia and NBG normative acts.'),
    (67, 'en', 'E', 'E-Signature', 'E-Signature', 'Information in electronic form attached to or logically associated with other electronic data and used to identify the signatory and confirm the integrity of an electronic document. Within these Regulations, a simple electronic signature is used in the meaning defined by applicable legislation of Georgia and the E-Signature Usage Agreement (Appendix No. 8 to the Regulations).'),
    (224, 'en', 'E', 'Electronic Document', 'Electronic Document', 'Information recorded in electronic form containing mandatory requisites enabling unambiguous identification of its content, author, and time of creation. An electronic document has legal force equivalent to a paper document, provided that an established method of electronic confirmation is used (electronic signature, SSO authentication, qualified identification means, or other methods recognized by the regulator).'),
    (135, 'en', 'E', 'Eligible Counterparty', 'Eligible Counterparty', 'A large and experienced market participant conducting significant trading operations (financial institutions, funds, etc.).'),
    (163, 'en', 'E', 'Equity', 'Equity', 'The Client’s own capital. Cash funds and securities of the Client held in the Brokerage Account, as well as cash funds and securities of the Client to be credited to the Brokerage Account as a result of settlements on transactions concluded by the Broker in the Client’s interests [from the Regulations].'),
    (190, 'en', 'E', 'Error Rate of Manual Operations', 'Error Rate of Manual Operations', 'The frequency of personnel errors when performing manual operations.'),
    (11, 'en', 'E', 'Eurobond', 'Eurobond', 'Bonds denominated in a currency other than the currency of the issuer’s country, issued by foreign governments and other public authorities, international organizations, large corporations and other legal entities, and traded on international capital markets.'),
    (32, 'en', 'E', 'Exchange / ATS', 'Exchange / ATS', 'A legal entity, including a foreign one (exchange, trading venue, broker, bank), ensuring the functioning of an organized market for securities, currencies, derivative financial instruments and other Instruments in accordance with the legislation of the relevant jurisdiction and its own Trading Rules.'),
    (43, 'en', 'E', 'Exchange Rules', 'Exchange Rules', 'Rules, regulations, instructions, procedures, regulatory documents or requirements of the Trading Organizer that are mandatory or recommended for execution by all trading participants on the relevant Trading Venue.'),
    (199, 'en', 'E', 'Execution Data', 'Execution Data', 'Information on trade execution.'),
    (188, 'en', 'E', 'Execution Latency', 'Execution Latency', 'Delay in the execution of Client orders.'),
    (139, 'en', 'E', 'Execution of Orders on Behalf of Clients', 'Execution of Orders on Behalf of Clients', 'Execution by the broker of transactions with financial instruments on behalf of the Client.'),
    (38, 'en', 'E', 'Expected Exposure', 'Expected Exposure', 'A value reflecting the potential impact of market changes on the Client’s assets in accordance with NBG requirements.'),
    (106, 'en', 'E', 'Expenses', 'Expenses', 'The Company’s expenses related to margin operations that are not included in the Compensation Sum.'),
    (107, 'en', 'E', 'Explanatory Note', 'Explanatory Note', 'A commentary to expense calculations, including accounting for dividends on securities that were included in the Client’s obligations as of the record date.'),
    (156, 'en', 'E', 'Exposure', 'Exposure', 'The total level of risk on an open position.'),
    (165, 'en', 'E', 'Exposure at Default (EAD)', 'Exposure at Default (EAD)', 'The risk of losses in the event of default.'),
    (162, 'en', 'E', 'Exposure Limits', 'Exposure Limits', 'The maximum permissible risk per instrument / Portfolio.'),
    (193, 'en', 'F', 'Failover', 'Failover', 'Switching to a backup circuit/component of the IT system.'),
    (57, 'en', 'F', 'Fee Schedule', 'Fee Schedule', 'A standard commercial offer form determined by the Broker, specifying the list of services provided and the procedure for determining their cost. The list of Fee Schedules and the conditions for their application are contained in Appendices No. 2 and 2a to the Agreement.'),
    (3, 'en', 'F', 'Fiduciary Standard', 'Fiduciary Standard', 'A basic principle for the protection of investors’ rights and interests, as defined by the legislation of Georgia.'),
    (19, 'en', 'F', 'Financial Instrument', 'Financial Instrument', 'The subject matter and main terms of a transaction (securities, derivative financial instruments, currency, etc.) that may be concluded by the Broker pursuant to the Client’s Instruction under the Agreement.'),
    (228, 'en', 'F', 'Financing of terrorism', 'Financing of terrorism', 'Any activity or operation aimed at the provision, collection, transfer, or use of funds or other assets for the purpose of supporting terrorist activity, a terrorist, or a terrorist organization, regardless of the lawful or unlawful origin of such funds.'),
    (115, 'en', 'F', 'FIX Interface', 'FIX Interface', 'A protocol for connecting external trading systems and algorithms to the broker; the cost depends on speed and the range of instruments.'),
    (121, 'en', 'F', 'FOP Transfers', 'FOP Transfers', 'Transfers of securities between brokers without cash settlement (settlement has already been performed earlier).'),
    (17, 'en', 'F', 'Foreign Currency', 'Foreign Currency', 'The official monetary unit of the relevant country or group of countries (including the euro), other than the Georgian lari.'),
    (18, 'en', 'F', 'Foreign Security', 'Foreign Security', 'A financial instrument recognized as a security under the legislation of the relevant foreign jurisdiction and traded on foreign organized and/or unorganized markets, the rights to which are recorded with a foreign depository, custodian, clearing organization, or other professional participant regulated by the competent authority of its jurisdiction.'),
    (180, 'en', 'F', 'Funding Gap', 'Funding Gap', 'The gap between sources of liquidity and liquidity needs.'),
    (73, 'en', 'F', 'Futures Contract Specification', 'Futures Contract Specification', 'A document establishing the standard terms of a futures contract: lot size, underlying asset, expiration date, settlement type, and tick size.'),
    (83, 'en', 'F', 'Futures Position', 'Futures Position', 'An obligation of a participant to buy (long) or sell (short) the underlying asset under a futures contract.'),
    (181, 'en', 'F', 'FX Exposure', 'FX Exposure', 'Open foreign exchange position.'),
    (182, 'en', 'F', 'FX GAP', 'FX GAP', 'Mismatch between assets and liabilities in a currency.'),
    (184, 'en', 'F', 'FX Sensitivity', 'FX Sensitivity', 'Portfolio response to changes in foreign exchange rates.'),
    (151, 'en', 'F', 'FX Transactions related to Investment Services', 'FX Transactions related to Investment Services', 'Currency transactions performed for the purpose of executing or supporting the Client’s investment transactions.'),
    (183, 'en', 'F', 'FX Volatility', 'FX Volatility', 'Variability of foreign exchange rates.'),
    (161, 'en', 'G', 'Gap Sensitivity', 'Gap Sensitivity', 'Sensitivity of the Portfolio to sharp price jumps.'),
    (9, 'en', 'G', 'Government-Issued ID', 'Government-Issued ID', 'One of the following documents: • passport of a citizen of Georgia; • identification card (ID Card) of a citizen of Georgia; • birth certificate of a citizen of Georgia (for citizens of Georgia under 14 years of age); • passport of a foreign citizen; • residence permit in Georgia or another document recognized by the legislation of Georgia as a proper identity document.'),
    (75, 'en', 'H', 'Hedging', 'Hedging', 'An operation to reduce market risk using offsetting transactions or derivatives.'),
    (234, 'en', 'I', 'Identification', 'Identification', 'The procedure for obtaining and recording identification data of the Client, the Client’s representative, and/or the beneficial owner in accordance with AML/CTF legislation requirements.'),
    (185, 'en', 'I', 'Incident Frequency', 'Incident Frequency', 'The number of operational incidents over a period.'),
    (133, 'en', 'I', 'Informed Investor (Accredited Investor)', 'Informed Investor (Accredited Investor)', 'A person recognized as such in accordance with Order of the President of the National Bank of Georgia No. 223/04 dated 16 December 2020 “On Approval of the Procedure for Recognition of a Person as an Informed Investor”, in accordance with the Procedure for Decision-Making on Recognition of Persons as Informed Investors of Rioni Capital LLC, published on the Broker’s Website, and in accordance with the Client Categorization Policy of the brokerage company “Rioni Capital”.'),
    (214, 'en', 'I', 'Infrastructure institution', 'Infrastructure institution', 'A prime broker, custodian, central securities depository, central counterparty, clearing organization, and other financial market infrastructure institutions.'),

    (166, 'en', 'I', 'Initial Margin (IM)', 'Initial Margin (IM)', 'The minimum collateral required to open a position. (In the Regulations: the required level of collateral for opening a position.)'),
    (70, 'en', 'I', 'Initial Margin / Performance Bond', 'Initial Margin / Performance Bond', 'A parameter of the Broker’s risk management system determined by the Clearing House and/or based on the Clearing House requirements for the amount of individual clearing collateral for the Client’s Portfolio. The amount of Initial Margin displayed in the Client’s software may differ from the amount calculated by the Clearing House; the Client is obliged to independently monitor the amount of Initial Margin.'),
    (127, 'en', 'I', 'Initial Public Offering (IPO)', 'Initial Public Offering (IPO)', 'Placement of a company’s shares on an exchange for the purpose of raising capital.'),
    (66, 'en', 'I', 'Instant Messaging System', 'Instant Messaging System', 'A channel for exchanging information and Notifications in real time within the software provided by the Broker to the Client.'),
    (108, 'en', 'I', 'Interest', 'Interest', 'An amount accrued for the use of borrowed funds and/or securities within margin transactions.'),
    (10, 'en', 'I', 'Interest Income', 'Interest Income', 'Any cash and/or other property received in respect of securities, including, but not limited to, dividends, interest, accrued coupon income, other types of income and distributions paid (transferred) by the issuer of securities or another person that issued the securities, net of taxes, fees, and other mandatory withholdings.'),
    (137, 'en', 'I', 'Investment Activities', 'Investment Activities', 'A set of actions of the Company within the scope of its license, including proprietary trading, custody of assets, and currency operations.'),
    (148, 'en', 'I', 'Investment Advice', 'Investment Advice', 'A personalized recommendation to the Client regarding the acquisition, sale, or holding of financial instruments.'),
    (7, 'en', 'I', 'Investment Adviser', 'Investment Adviser', 'A management company or fund managing assets or funds on the basis of a license.'),
    (16, 'en', 'I', 'Investment Advisory Services', 'Investment Advisory Services', 'The Broker’s service of providing the Client with personalized investment advice in accordance with the Agreement and Appendix No. 12 to the Regulations, as well as other internal documents of the Broker and the legislation of Georgia.'),
    (146, 'en', 'I', 'Investment Company Act of 1940 & Investment Advisers Act of 1940', 'Investment Company Act of 1940 & Investment Advisers Act of 1940', 'The SEC regulatory framework governing the activities of funds and investment advisers; analogous to PRIIPs in terms of risk disclosure and duties toward retail investors.'),
    (152, 'en', 'I', 'Investment Research / Financial Analysis', 'Investment Research / Financial Analysis', 'Analytical activities aimed at providing information and forecasts on financial instruments and markets.'),
    (136, 'en', 'I', 'Investment Services', 'Investment Services', 'Activities licensed to the Company: reception and execution of orders, portfolio management, investment advice, etc.'),
    (155, 'en', 'I', 'Investment Services License', 'Investment Services License', 'Authorization issued by the regulator (NBG/EU) to provide investment and ancillary services.'),
    (217, 'en', 'I', 'ISLA', 'ISLA', 'An international association establishing standards and best practices for the securities lending market, including rules on securities return, income compensation, collateral management, and operational interaction among participants.'),
    (204, 'en', 'I', 'Issuer Concentration Limit', 'Issuer Concentration Limit', 'The maximum limit per single issuer.'),
    (2, 'en', 'K', 'KYC Data', 'KYC Data', 'Information about the Client, its representatives, and beneficial owners, provided to the Broker as part of the questionnaire and supporting documents.'),
    (192, 'en', 'L', 'Latency', 'Latency', 'Response delay.'),
    (150, 'en', 'L', 'Lending / Credit in respect of Financial Instruments', 'Lending / Credit in respect of Financial Instruments', 'Granting credit or a loan to the Client for transactions with financial instruments, with the Company participating in the transaction.'),
    (74, 'en', 'L', 'Leverage', 'Leverage', 'The ratio between the volume of an open position and the Client’s own funds, used to increase potential returns (and risk).'),
    (42, 'en', 'L', 'Limit Order', 'Limit Order', 'An Instruction to conclude a transaction at the price specified in the Instruction or at a price more favorable to the Client.'),
    (207, 'en', 'L', 'Liquidity Constraint', 'Liquidity Constraint', 'Limitation of positions based on liquidity.'),
    (179, 'en', 'L', 'Liquidity Coverage Ratio', 'Liquidity Coverage Ratio', 'The ratio of liquid assets to liabilities.'),
    (175, 'en', 'L', 'Liquidity Score', 'Liquidity Score', 'An indicator of an instrument’s liquidity.'),
    (126, 'en', 'L', 'Lock-up Period', 'Lock-up Period', 'A period established by the issuer (usually 90 days or more) during which shares may not be sold after placement.'),
    (110, 'en', 'L', 'Long Position', 'Long Position', 'A position arising from the purchase of an asset with the expectation of an increase in its market value.'),
    (89, 'en', 'M', 'Maintenance Margin', 'Maintenance Margin', 'The minimum margin level that the Client is required to maintain in order to keep open positions.'),
    (167, 'en', 'M', 'Maintenance Margin (MM)', 'Maintenance Margin (MM)', 'The minimum collateral required to maintain positions.'),
    (99, 'en', 'M', 'Margin Call', 'Margin Call', 'A notification from the Broker to the Client of the need to replenish the account or close positions in order to restore the required CAR level.'),
    (169, 'en', 'M', 'Margin Call Trigger', 'Margin Call Trigger', 'The margin level at which a margin call is issued to the Client (a requirement to provide additional collateral or close the position to the required extent).'),
    (213, 'en', 'M', 'Margin Close-Out Level / Liquidation Level / Close-Out', 'Margin Close-Out Level / Liquidation Level / Close-Out', 'The collateral level upon reaching which the Broker initiates forced liquidation of the Client’s position.'),
    (170, 'en', 'M', 'Margin Close-Out Trigger', 'Margin Close-Out Trigger', 'The collateral level upon reaching which the Broker initiates forced liquidation of the Client’s position.'),
    (168, 'en', 'M', 'Margin Level', 'Margin Level', 'The ratio of equity to required margin.'),
    (100, 'en', 'M', 'Margin Loan', 'Margin Loan', 'Cash or securities provided by the Company to the Client for execution of margin transactions.'),
    (101, 'en', 'M', 'Margin Requirements', 'Margin Requirements', 'The amount of collateral required by the Company from the Client to open and maintain a margin position.'),
    (102, 'en', 'M', 'Margin Transaction', 'Margin Transaction', 'A transaction executed by the Client using leverage provided by the Broker (margin loan).'),
    (98, 'en', 'M', 'Marginable Assets', 'Marginable Assets', 'Client assets that may be used as collateral for margin transactions.'),
    (71, 'en', 'M', 'Mark-to-Market Margin', 'Mark-to-Market Margin', 'Variation margin calculated by the Clearing House according to the variation margin calculation formula during a clearing session using the current settlement price of the i-th futures contract. The total Mark-to-Market Margin in the i-th currency forms the Client’s obligations/claims and is included in the Expected Position for the corresponding currency. The Client is obliged to independently monitor the Mark-to-Market Margin.'),
    (46, 'en', 'M', 'Market', 'Market', 'A place for concluding transactions with Instruments of a certain type, determined by the Broker. Within the Agreement, the Broker distinguishes, inter alia, the equity market, derivatives market, and foreign exchange market.'),
    (187, 'en', 'M', 'Market Data Delay', 'Market Data Delay', 'Delay in the provision of up-to-date market quotations.'),
    (177, 'en', 'M', 'Market Depth (DOM)', 'Market Depth (DOM)', 'Order book structure and a liquidity indicator.'),
    (41, 'en', 'M', 'Market Order', 'Market Order', 'An Instruction to conclude a transaction at the price available to the Broker on the relevant trading venue at the time of execution of the Instruction (without specifying a price limit). The Trading Organizer may set maximum permissible price deviations when executing such Instructions; information about this may be obtained by the Client on the official website of the relevant Trading Organizer.'),
    (202, 'en', 'M', 'Maximum Leverage', 'Maximum Leverage', 'The maximum permissible leverage.'),
    (229, 'en', 'M', 'Money laundering', 'Money laundering', 'Any actions or operations aimed at concealing or disguising the illegal origin of assets or proceeds obtained by criminal means, or at giving them the appearance of lawful origin, as defined by the AML/CTF legislation of Georgia.'),
    (29, 'en', 'N', 'National Bank of Georgia (NBG)', 'National Bank of Georgia (NBG)', 'The central bank of Georgia exercising supervision and regulation of financial institutions, including brokerage companies, in accordance with the legislation of Georgia.'),
    (103, 'en', 'N', 'Net Asset Value (NAV)', 'Net Asset Value (NAV)', 'The market value of the Client’s assets minus all obligations to the Company.'),
    (84, 'en', 'N', 'Netting', 'Netting', 'A process of offsetting mutual obligations between parties in order to reduce the total volume of settlements and risks.'),
    (164, 'en', 'N', 'NLV — Net Liquidation Value', 'NLV — Net Liquidation Value', 'The liquidation value of the Portfolio.'),
    (97, 'en', 'N', 'Non-marginable Assets (NMI)', 'Non-marginable Assets (NMI)', 'Client assets that are not accepted as collateral for margin transactions.'),
    (113, 'en', 'N', 'Non-standard Report', 'Non-standard Report', 'An individual account report generated upon request (audit, tax authorities, court, etc.).'),

    (123, 'en', 'N', 'Non-trading Orders', 'Non-trading Orders', 'Orders not directly related to trading operations (for example, transfers, reporting).'),
    (223, 'en', 'N', 'Notification', 'Notification', 'Any directive or informational message sent by the Broker to the Client or by the Client to the Broker in the course of performance of the Agreement, including via the Client Portal, Trading Platform, e- mail, Chat, and other agreed communication channels.'),
    (154, 'en', 'O', 'Offering of Investment Products', 'Offering of Investment Products', 'Sale to Clients of financial instruments corresponding to their risk profile and investment objectives.'),
    (35, 'en', 'O', 'Official Exchange Rate', 'Official Exchange Rate', 'The exchange rate established and published by the National Bank of Georgia (NBG).'),
    (218, 'en', 'O', 'Onboarding System', 'Onboarding System', 'An authorized organizational and technical remote service system (software) used by the Broker and the Client to support the Client onboarding process: remote client identification, document exchange, conclusion of the Brokerage Agreement, and opening of a Brokerage Account. Access is provided to the Client via a web service and/or a mobile application.'),
    (220, 'en', 'O', 'Open Contract', 'Open Contract', 'The number of open (concluded) derivative (futures or options) contracts in the Client’s Portfolio that have not been settled at the current time, i.e., are pending settlement completion or contract expiration.'),
    (77, 'en', 'O', 'Open Interest', 'Open Interest', 'The total number of outstanding (not closed and not executed) contracts for a specific futures contract or option.'),
    (30, 'en', 'O', 'Open Position', 'Open Position', 'An unclosed buy or sell transaction in an asset, maintaining potential profit or loss until it is closed.'),
    (82, 'en', 'O', 'Option Expiration', 'Option Expiration', 'The date on which an option expires, after which the contract loses its validity and ceases to be tradable.'),
    (79, 'en', 'O', 'Option Premium', 'Option Premium', 'The price paid by the option buyer to the seller for the right (but not the obligation) to buy or sell the underlying asset at a specified price.'),
    (81, 'en', 'O', 'Option Type (Call / Put)', 'Option Type (Call / Put)', 'Determines the right to buy (Call) or sell (Put) the underlying asset at a fixed price.'),
    (12, 'en', 'O', 'Order Ticket', 'Order Ticket', 'An instruction-type message for concluding transactions, submitted by the Broker (as a trading participant) to the Trading Organizer in the manner and on the terms established by the Trading Rules, for the purpose of executing the Client’s Instruction.'),
    (130, 'en', 'O', 'Over-the-Counter (OTC) Market', 'Over-the-Counter (OTC) Market', 'A venue or form of trading where transactions are concluded directly between counterparties rather than through an exchange.'),
    (15, 'en', 'P', 'Personalized Investment Advice', 'Personalized Investment Advice', 'Information addressed to a specific Client about securities, derivative financial instruments, currency and/or transactions with them, prepared taking into account the Client’s objectives, experience, financial situation, and attitude to risk, meeting the requirements of Georgian legislation, NBG normative acts, and the Broker’s internal documents governing investment advisory activities.'),
    (237, 'en', 'P', 'Politically Exposed Person (PEP)', 'Politically Exposed Person (PEP)', 'A natural person who is or has been entrusted with prominent public functions, as well as members of their family and persons closely associated with them, as defined by AML/CTF legislation and regulatory requirements.'),
    (147, 'en', 'P', 'Portfolio Management', 'Portfolio Management', 'Activities related to discretionary management of the Client’s assets based on the Client’s investment objectives and strategy.'),
    (54, 'en', 'P', 'Portfolio Value', 'Portfolio Value', 'The aggregate of the Client’s Expected Positions of one Portfolio, expressed in Georgian lari (or in a foreign currency if provided for by the Agreement). The Portfolio Value displayed in the Trading System software used by the Client for exchanging Notifications with the Broker may differ from the value calculated by the Broker and disclosed in the Client Portal; the Client is obliged to independently monitor the value of any of its Portfolios.'),
    (33, 'en', 'P', 'Primary Contact Number', 'Primary Contact Number', 'The Client’s primary mobile phone number specified in the questionnaire and provided by the telecommunications operator.'),
    (197, 'en', 'P', 'Primary Market Data', 'Primary Market Data', 'Price information received from exchanges.'),
    (61, 'en', 'P', 'Prime Broker / Executing Broker', 'Prime Broker / Executing Broker', 'A foreign or Georgian professional market participant holding the relevant license/authorization to carry out brokerage activities, through which the Broker executes Clients’ Instructions on foreign trading venues and/or organized markets.'),
    (34, 'en', 'P', 'Principal Office', 'Principal Office', 'The principal place of business of the Broker and its divisions, as indicated on the Company’s website.'),
    (134, 'en', 'P', 'Professional Client', 'Professional Client', 'A client possessing sufficient knowledge, experience, and assets to understand risks and receiving limited protection under MiFID II.'),
    (52, 'en', 'Q', 'Qualified Custodian', 'Qualified Custodian', 'An organization carrying out the activity of a specialized custodian of investment funds, pension schemes and/or other collective investment institutions on the basis of a license or other authorization issued by a competent authority in accordance with the legislation of Georgia or the relevant foreign jurisdiction.'),
    (178, 'en', 'Q', 'Quick Ratio', 'Quick Ratio', 'Coverage of liabilities by liquid assets.'),
    (50, 'en', 'Q', 'Quote Currency', 'Quote Currency', 'The currency in which the price of an instrument is expressed or in which settlement under a conversion transaction is carried out.'),
    (119, 'en', 'R', 'Real-time Market Data', 'Real-time Market Data', 'A stream of quotations and trading information provided on a subscription basis.'),
    (238, 'en', 'R', 'Reasonable Assumption', 'Reasonable Assumption', 'A conclusion or assumption based on facts, documents, behavioral indicators, transaction patterns, or other objective data sufficient for AML/CTF assessment, initiation of additional analysis, and/or a decision on further actions.'),
    (138, 'en', 'R', 'Reception and Transmission of Orders', 'Reception and Transmission of Orders', 'A service for receiving instructions from the Client and transmitting them to third parties for execution.'),
    (122, 'en', 'R', 'Redomiciliation', 'Redomiciliation', 'Re-registration of a legal entity or fund in another jurisdiction while preserving the ownership structure.'),
    (200, 'en', 'R', 'Reference Prices', 'Reference Prices', 'Prices used for asset valuation.'),
    (36, 'en', 'R', 'Referral Partner', 'Referral Partner', 'A legal entity with which the Broker has entered into a paid services agreement for the search and attraction of potential clients, as well as for organizing document flow between the Broker and the Client, including via a dedicated website (web interface) on the Internet.'),
    (143, 'en', 'R', 'Regulation (EU) No 1286/2014 on Key Information Documents for Packaged Retail and Insurance-based Investment Products (PRIIPs)', 'Regulation (EU) No 1286/2014 on Key Information Documents for Packaged Retail and Insurance-based Investment Products (PRIIPs)', 'An EU regulation establishing requirements for the content and provision of Key Information Documents (KIDs) for transparency and protection of retail investors.'),
    (142, 'en', 'R', 'Regulation (EU) No 600/2014 on Markets in Financial Instruments (MiFIR)', 'Regulation (EU) No 600/2014 on Markets in Financial Instruments (MiFIR)', 'An EU regulation supplementing MiFID II; regulates trade execution, reporting, transparency, and market access.'),
    (231, 'en', 'R', 'Related Transactions', 'Related Transactions', 'Several interrelated transactions or operations united by a common economic substance, purpose, participants, source or destination of funds, or other characteristics which, for AML/CTF purposes, are subject to review in aggregate.'),
    (131, 'en', 'R', 'Reporting Format', 'Reporting Format', 'The structure for presenting brokerage reports used for calculations and audits.'),
    (239, 'en', 'R', 'Responsible Employee', 'Responsible Employee', 'An employee of the Broker appointed to perform AML/CTF control functions, including Client identification and verification, transaction monitoring, escalation of suspicious cases, and interaction with competent authorities in accordance with legislation and internal policies.'),
    (225, 'en', 'R', 'Responsible Person', 'Responsible Person', 'A person or organization entrusted, in accordance with the legislation of Georgia in the field of AML/CTF, with duties to prevent, detect, and control money laundering and terrorist financing risks, including compliance with established procedures and requirements (including financial institutions such as brokerage companies).'),
    (132, 'en', 'R', 'Retail Client', 'Retail Client', 'A client who is not a professional or eligible counterparty and receives the maximum level of regulatory protection.'),
    (157, 'en', 'R', 'Return', 'Return', 'Change in the value of an instrument over a period.'),
    (209, 'en', 'R', 'Risk Groups', 'Risk Groups', 'A set of parameters of the Broker’s Risk Management System (RMS) applied to a specific Client Portfolio. The list of Risk Groups and their parameters are determined by the Broker and published on the Broker’s Website.'),
    (208, 'en', 'R', 'Risk Weight', 'Risk Weight', 'A risk weight used in the calculation of IM/MM.'),
    (53, 'en', 'R', 'Round Lot / Standard Lot', 'Round Lot / Standard Lot', 'The minimum quantity of an instrument determined by the trading venue for concluding transactions.'),
    (196, 'en', 'R', 'RPO (Recovery Point Objective)', 'RPO (Recovery Point Objective)', 'The acceptable data loss.'),
    (195, 'en', 'R', 'RTO (Recovery Time Objective)', 'RTO (Recovery Time Objective)', 'The acceptable recovery time.'),
    (129, 'en', 'S', 'Safekeeping', 'Safekeeping', 'A service for the secure custody of the Client’s securities and assets in a depository or with a custodian.'),
    (48, 'en', 'S', 'Sanctions Restrictions', 'Sanctions Restrictions', 'Any restrictive measures (including economic, financial, trade sanctions and other restrictions) adopted or imposed by: • state authorities of Georgia; • authorities of foreign states, unions of states, international organizations (including, but not limited to, the United Nations Organisation, the United States Department of the Treasury, the Council of the European Union, HM Treasury, the Office of Foreign Assets Control), in respect of states, persons, currencies, financial instruments or transactions, and prohibiting directly or indirectly: i. purchase, sale, or investment; ii. servicing, financial intermediation, participation in primary offerings; iii. entering into and/or executing certain or all types of transactions with financial instruments; iv. making payments and/or transactions necessary for execution of the Client’s Instructions or obligations under transactions in the Client’s interests. Sanctions Restrictions include, in particular, the inclusion of the relevant persons in the U.S. Treasury sanctions list “SDN List”, as well as in other official sanctions lists.'),
    (198, 'en', 'S', 'Secondary Market Data', 'Secondary Market Data', 'Price information received from data aggregators.'),
    (128, 'en', 'S', 'Secondary Public Offering (SPO)', 'Secondary Public Offering (SPO)', 'An additional issuance of shares of a company already traded on an exchange.'),
    (205, 'en', 'S', 'Sector Exposure Limit', 'Sector Exposure Limit', 'The maximum limit per single sector.'),
    (64, 'en', 'S', 'Securities', 'Securities', 'Issued and non-issued securities, including shares, bonds, investment units, other equity and debt instruments, as well as foreign securities recognized as such in accordance with the legislation of Georgia and/or applicable legislation of relevant foreign jurisdictions.'),

    (144, 'en', 'S', 'Securities Exchange Act of 1934', 'Securities Exchange Act of 1934', 'A fundamental U.S. law regulating the secondary securities market, the activities of broker-dealers and exchanges; functionally analogous to MiFID II in terms of regulation of services and disclosure.'),
    (86, 'en', 'S', 'Settlement Account', 'Settlement Account', 'A special account used for conducting clearing settlements and mutual settlements between participants.'),
    (173, 'en', 'S', 'Settlement Delay', 'Settlement Delay', 'Clearing delay. Delay in settlements on transactions and operations.'),
    (76, 'en', 'S', 'Settlement Price', 'Settlement Price', 'A price established by the Clearing House for the calculation of variation margin and participants’ obligations.'),
    (45, 'en', 'S', 'Shareholder Register', 'Shareholder Register', 'A list of persons (holders of securities) entitled to receive income on securities and other payments/distributions, compiled by the issuer of securities or another authorized person in accordance with applicable legislation.'),
    (109, 'en', 'S', 'Short Position', 'Short Position', 'A position arising from the sale of securities without coverage (expectation of a price decrease).'),
    (24, 'en', 'S', 'Spot FX Transaction', 'Spot FX Transaction', 'A purchase and sale transaction of foreign currency on organized foreign exchange markets.'),
    (176, 'en', 'S', 'Spread Indicator', 'Spread Indicator', 'Deviation of the current spread from the average statistical spread.'),
    (55, 'en', 'S', 'Stop Order / Stop-Limit Order', 'Stop Order / Stop-Limit Order', 'An Instruction at a limit or market price for an exchange transaction with deferred conditions provided for by the functional capabilities of the software, execution of which becomes mandatory for the Broker after occurrence of the conditions for order placement and/or transaction conclusion specified in the Instruction.'),
    (201, 'en', 'S', 'Stress Prices', 'Stress Prices', 'Prices used for stress testing.'),
    (160, 'en', 'S', 'Stress-Loss', 'Stress-Loss', 'Portfolio loss under stressed market movements.'),
    (117, 'en', 'S', 'Structured Products', 'Structured Products', 'Complex financial instruments combining securities and derivatives.'),
    (27, 'en', 'S', 'Sub-Account', 'Sub-Account', 'A structural unit of the Broker’s internal accounting, constituting part of the Client’s Portfolio and intended for recording the quantity of the Client’s Property and Liabilities by reflecting transactions and operations with the Client’s securities, derivatives, precious metals, and cash. Within one Client Portfolio, at least one Sub-Account is opened; the number and structure of personal accounts are determined by the Client and/or the Broker in accordance with the Agreement.'),
    (56, 'en', 'S', 'Sub-Broker / Introducing Broker', 'Sub-Broker / Introducing Broker', 'A Client of the Broker who is a professional participant of the securities market and carries out brokerage activities in the interests and on behalf of its clients on the basis of a license or other authorization of the regulator of the country of registration of such Client.'),
    (232, 'en', 'S', 'Suspicious Transaction', 'Suspicious Transaction', 'A transaction, operation, or an attempt thereof in respect of which there are reasonable grounds to believe that it may be related to money laundering, terrorist financing, sanctions evasion, or other unlawful purposes and is therefore subject to analysis and, where necessary, reporting to the competent authorities.'),
    (240, 'en', 'S', 'Suspicious Zone', 'Suspicious Zone', 'A corporate term (not a mandatory legal definition): a geographical area, jurisdiction, client segment, type of activity, or operational channel with elevated AML/CTF risk, identified by the Broker’s internal risk assessment and/or communications from competent authorities, in respect of which enhanced control and monitoring measures are applied.'),
    (116, 'en', 'S', 'Swaps and Structured Notes', 'Swaps and Structured Notes', 'OTC derivatives concluded directly between participants, outside an exchange.'),
    (186, 'en', 'S', 'System Outages', 'System Outages', 'Unavailability of critical IT systems.'),
    (91, 'en', 'T', 'Tick Size', 'Tick Size', 'The minimum possible price change of a financial instrument established by the contract specification.'),
    (62, 'en', 'T', 'Trade Execution / Filled Order', 'Trade Execution / Filled Order', 'A fully or partially executed Client Instruction having a unique number in the Broker’s system.'),
    (59, 'en', 'T', 'Trading Fee', 'Trading Fee', 'An additional remuneration of the Broker for executing exchange transactions on behalf of the Client, in accordance with the Fee Schedule.'),
    (215, 'en', 'T', 'Trading Platform', 'Trading Platform', 'An information and trading remote-access system provided by the Broker to the Client for transmitting Messages and Orders electronically via the Internet. The list of trading systems and software used by the Broker may be expanded and is specified on the Broker’s Website and/or in the Appendices to the Agreement.'),
    (60, 'en', 'T', 'Trading Session / Market Day', 'Trading Session / Market Day', 'The period of time during which Trading Organizers conduct trading. The list of available Trading Organizers and their schedules is published on the Broker’s Website.'),
    (230, 'en', 'T', 'Transactions', 'Transactions', 'Any operation or set of actions of the Client or the Broker related to financial instruments, funds, currency, or other assets, including submission and execution of orders, transfers, conversion, and settlements, for AML/CTF control purposes.'),
    (219, 'en', 'U', 'Uncovered Position', 'Uncovered Position', 'A negative value of the Client’s Planned Position formed within the Portfolio by a specific type of Assets; the amount of the Uncovered Position is increased by the Broker by the amount of the Client’s Liabilities.'),
    (80, 'en', 'U', 'Underlying Asset', 'Underlying Asset', 'A financial instrument, commodity, or indicator on which a derivative financial instrument is based. This may be a security, commodity, currency, interest rate, or other indicator.'),
    (233, 'en', 'U', 'Unusual Transaction', 'Unusual Transaction', 'A transaction or operation which, by its amount, frequency, structure, economic substance, or inconsistency with the Client’s profile, is atypical and requires additional analysis for AML/CTF purposes; an unusual transaction may, but does not necessarily have to, be recognized as suspicious.'),
    (191, 'en', 'U', 'Uptime', 'Uptime', 'Service availability percentage.'),
    (159, 'en', 'V', 'Value-at-Risk (VaR)', 'Value-at-Risk (VaR)', 'The maximum expected loss over a specified confidence interval.'),
    (69, 'en', 'V', 'Variation Margin', 'Variation Margin', 'An amount of funds calculated by the Clearing House during a clearing session and subject to crediting to or debiting from the Sub-Account for each concluded futures contract and/or Open Position formed during previous clearing sessions, in accordance with the Specification of the relevant futures contract.'),
    (235, 'en', 'V', 'Verification', 'Verification', 'Verification of the accuracy of identification data of the Client, the Client’s representative, and/or the beneficial owner on the basis of documents, information, or reliable sources, in the manner established by AML/CTF requirements.'),
    (158, 'en', 'V', 'Volatility', 'Volatility', 'A statistical measure of price variability.'),
    (95, 'ge', 'ა', 'ანალიტიკური ღირებულება', 'Analytical Value', 'ფასიანი ქაღალდების გადაფასებული საბაზრო ან ანგარიშობითი სამართლიანი ღირებულება მარჟინალურ გარიგებაში დარიცხული პროცენტების გათვალისწინებით.'),
    (131, 'ge', 'ა', 'ანგარიშგების ფორმატი', 'Reporting Format', 'საბროკერო ანგარიშგებების წარმოდგენის სტრუქტურა, რომელიც გამოიყენება ანგარიშსწორებისა და აუდიტის მიზნებისთვის.'),
    (225, 'ge', 'ა', 'ანგარიშვალდებული პირი', 'Responsible Person / Obliged Entity', 'ამ რეგლამენტის მიზნებისთვის — პირი/ორგანიზაცია, რომელსაც საქართველოს AML/CTF კანონმდებლობით ეკისრება ფულის გათეთრებისა და ტერორიზმის დაფინანსების პრევენციის, გამოვლენისა და შესაბამისი პროცედურების შესრულების ვალდებულებები (მათ შორის ფინანსური ინსტიტუტები, როგორიცაა საბროკერო კომპანია). (fms.gov.ge)'),
    (173, 'ge', 'ა', 'ანგარიშსწორების დაყოვნება', 'Settlement Delay', 'კლირინგისა და ანგარიშსწორების დაყოვნება გარიგებებსა და ოპერაციებზე.'),
    (191, 'ge', 'ა', 'აპთაიმი', 'Uptime', 'სერვისის ხელმისაწვდომობის პროცენტული მაჩვენებელი.'),
    (97, 'ge', 'ა', 'არამარჟირებადი აქტივები', 'Non-marginable Assets (NMI)', 'კლიენტის აქტივები, რომლებიც არ მიიღება უზრუნველყოფად მარჟინალური ოპერაციებისათვის.'),
    (130, 'ge', 'ა', 'არასაბირჟო ბაზარი (OTC)', 'Over-the-Counter (OTC) Market', 'სავაჭრო გარემო ან ფორმა, სადაც გარიგებები იდება უშუალოდ კონტრაგენტებს შორის და არა ბირჟის მეშვეობით.'),
    (123, 'ge', 'ა', 'არასავაჭრო ბრძანებები', 'Non-trading Orders', 'განაცხადები, რომლებიც უშუალოდ არ არის დაკავშირებული სავაჭრო ოპერაციებთან (მაგალითად, გადარიცხვა, ანგარიშგება).'),
    (113, 'ge', 'ა', 'არასტანდარტული ანგარიშგება', 'Non-standard Report', 'ინდივიდუალური ანგარიშგება ანგარიშზე, რომელიც ფორმირდება მოთხოვნის საფუძველზე (აუდიტი, საგადასახადო ორგანოები, სასამართლო და სხვა).'),
    (219, 'ge', 'ა', 'არაუზრუნველყოფილი პოზიცია', 'Uncovered Position', 'კლიენტის პორტფელის ფარგლებში კონკრეტული სახის ქონების მიხედვით ფორმირებული გეგმიური პოზიციის უარყოფითი მნიშვნელობა; არაუზრუნველყოფილი პოზიციის ოდენობა იზრდება ბროკერის მიერ კლიენტის ვალდებულებების ოდენობით.'),
    (7, 'ge', 'ა', 'აქტივების მმართველი', 'Investment Adviser', 'მმართველი კომპანია ან ფონდი, რომელიც ლიცენზიის საფუძველზე ახორციელებს აქტივების ან ფონდების მართვას.'),
    (129, 'ge', 'ა', 'აქტივების შენახვა', 'Safekeeping', 'კლიენტის ფასიანი ქაღალდებისა და აქტივების უსაფრთხო შენახვის მომსახურება დეპოზიტარში ან კასტოდიანთან.'),
    (103, 'ge', 'ა', 'აქტივების წმინდა ღირებულება', 'Net Asset Value (NAV)', 'კლიენტის აქტივების საბაზრო ღირებულება კომპანიის წინაშე არსებული ყველა ვალდებულების გამოკლებით.'),
    (45, 'ge', 'ა', 'აქციონერთა რეესტრი', 'Shareholder Register', 'პირების სია (ფასიანი ქაღალდების მფლობელები), რომელთაც აქვთ უფლება მიიღონ შემოსავლები ფასიანი ქაღალდებიდან და სხვა გადახდები/განაწილებები, რომელიც შედგენილია ფასიანი ქაღალდების ემიტენტის ან სხვა უფლებამოსილი პირის მიერ შესაბამისი კანონმდებლობის შესაბამისად.'),
    (46, 'ge', 'ბ', 'ბაზარი', 'Market', 'ბროკერის მიერ განსაზღვრული ადგილი კონკრეტული ტიპის ინსტრუმენტებთან დაკავშირებული გარიგებების დასადებად. ხელშეკრულების ფარგლებში ბროკერი გამოყოფს, მათ შორის, საფონდო ბაზარს, სროჩიან ბაზარს და სავალუტო ბაზარს.'),
    (177, 'ge', 'ბ', 'ბაზრის სიღრმე (DOM)', 'Market Depth (DOM)', 'შეკვეთების წიგნის სტრუქტურა და ლიკვიდურობის ინდიკატორი.'),
    (4, 'ge', 'ბ', 'ბანკი / ბანკი კასტოდიანი', 'Bank / Custodian Bank', 'ნებისმიერი ბანკი, რომელშიც ბროკერს გახსნილი აქვს საბანკო ანგარიშები კლიენტების ოპერაციებზე ანგარიშსწორების განსახორციელებლად და/ან საკუთარი საქმიანობის მიზნებისთვის.'),
    (226, 'ge', 'ბ', 'ბენეფიციარი მესაკუთრე', 'Beneficial Owner', 'ფიზიკური პირი (პირები), რომელიც საბოლოოდ ფლობს ან აკონტროლებს კლიენტს და/ან სახელითაც ხორციელდება გარიგება/ოპერაცია, მათ შორის საკუთრებისა და კონტროლის სტრუქტურის მეშვეობით (პირდაპირ ან არაპირდაპირ). (Бухгалтерский надзор)'),

    (211, 'ge', 'ბ', 'ბროკერი', 'Broker', 'Rioni Capital LLC — ფასიანი ქაღალდების ბაზრის პროფესიონალი მონაწილე, რომელსაც გააჩნია საქართველოს ეროვნული ბანკის მიერ გაცემული საბროკერო ლიცენზია და რომელიც მოქმედებს კლიენტის სახელითა და ხარჯზე ან საკუთარი სახელით და კლიენტის ხარჯზე ფინანსურ ინსტრუმენტებთან დაკავშირებული გარიგებების დადებისას ანაზღაურების (საკომისიოს) სანაცვლოდ.'),
    (12, 'ge', 'ბ', 'ბროკერის ბრძანება / განაცხადი', 'Order Ticket', 'განკარგულებითი ხასიათის შეტყობინება გარიგების დასადებად, რომელსაც ბროკერი (როგორც სავაჭრო მონაწილის სტატუსით) წარადგენს ვაჭრობის ორგანიზატორთან სავაჭრო წესებით დადგენილი წესითა და პირობებით, კლიენტის დავალების შესასრულებლად.'),
    (47, 'ge', 'ბ', 'ბროკერის ვებგვერდი', 'Broker’s Website', 'კომპანიის ოფიციალური ვებგვერდი (www.rioni-capital.ge), რომელიც შეიცავს ინფორმაციასა და დოკუმენტებს კლიენტებისთვის.'),
    (34, 'ge', 'ბ', 'ბროკერის ოფისი', 'Principal Office', 'ბროკერისა და მისი ქვედანაყოფების ძირითადი მდებარეობა, რომელიც მითითებულია კომპანიის ვებ-საიტზე.'),
    (49, 'ge', 'ბ', 'ბროკერის შეტყობინება', 'Broker Notification', 'ნებისმიერი ადმინისტრაციული ან საინფორმაციო შეტყობინება, რომელიც იცვლება ბროკერსა და კლიენტს შორის ხელშეკრულების შესრულების პროცესში.'),
    (241, 'ge', 'ბ', 'ბროკერი (კომპანია, შპს „რიონი კაპიტალი“)', 'Broker (Company, Rioni Capital LLC)', 'საბროკერო კომპანია შპს რიონი კაპიტალი, რომელსაც აქვს საქართველოს ეროვნული ბანკის ლიცენზია საბროკერო საქმიანობის განსახორციელებლად და რომელიც ფინანსურ ინსტრუმენტებთან დაკავშირებული გარიგებების დადებისას მოქმედებს კლიენტის სახელით და კლიენტის ხარჯზე ან საკუთარი სახელით და კლიენტის ხარჯზე. დემატერიალიზებულ ფასიან ქაღალდებზე კლიენტის უფლებების აღრიცხვის ნაწილში ბროკერი მოქმედებს როგორც „ანგარიშის მწარმოებელი“ საქართველოს კანონის „დემატერიალიზებული ფასიანი ქაღალდების ფლობის შესახებ“ მნიშვნელობით და უზრუნველყოფს აღნიშნული უფლებების აღრიცხვას დეპოზიტარში/კასტოდიანთან.'),
    (133, 'ge', 'გ', 'გათვითცნობიერებული კლიენტი', 'Informed Investor (Accredited Investor)', 'პირი, რომელიც აღიარებულია ინფორმირებულ ინვესტორად საქართველოს ეროვნული ბანკის პრეზიდენტის 2020 წლის 16 დეკემბრის №223/04 ბრძანების შესაბამისად და Rioni Capital LLC-ის მიერ დადგენილი წესით, რომელიც გამოქვეყნებულია ბროკერის ვებგვერდზე და შეესაბამება კლიენტების კატეგორიზაციის პოლიტიკას.'),
    (107, 'ge', 'გ', 'განმარტებითი ჩანაწერი', 'Explanatory Note', 'ხარჯების გაანგარიშების კომენტარი, მათ შორის დივიდენდების აღრიცხვა იმ ფასიან ქაღალდებზე, რომლებიც კლიენტის ვალდებულებებში იმყოფებოდა ფიქსაციის თარიღზე.'),
    (230, 'ge', 'გ', 'გარიგება', 'Transaction', 'კლიენტის ან ბროკერის მიერ განხორციელებული ოპერაცია/ქმედება ფინანსურ ინსტრუმენტებთან, ფულთან, ვალუტასთან ან სხვა აქტივებთან დაკავშირებით, მათ შორის ბრძანების წარდგენა, შესრულება, გადარიცხვა, კონვერტაცია და სხვ. (კორპორაციული განმარტება AML მიზნებისთვის, კანონთან თავსებადი). (fms.gov.ge)'),
    (38, 'ge', 'გ', 'გეგმიური პოზიცია', 'Expected Exposure', 'სიდიდე, რომელიც ასახავს საბაზრო ცვლილებების პოტენციურ ზემოქმედებას კლიენტის აქტივებზე ნბგ-ს მოთხოვნების შესაბამისად.'),
    (161, 'ge', 'გ', 'გეპის მგრძნობელობა', 'Gap Sensitivity', 'პორტფელის მგრძნობელობა ფასის მკვეთრი ნახტომების მიმართ.'),
    (110, 'ge', 'გ', 'გრძელი პოზიცია', 'Long Position', 'პოზიცია, რომელიც წარმოიშობა აქტივის შეძენისას მისი საბაზრო ღირებულების ზრდის მოლოდინით.'),
    (231, 'ge', 'დ', 'დაკავშირებული გარიგებები', 'Related Transactions', 'ერთმანეთთან დაკავშირებული (ურთიერთდამოკიდებული) რამდენიმე გარიგება/ოპერაცია, რომლებიც შესრულებულია ერთი საერთო მიზნის, ეკონომიკური არსის, მონაწილე პირების, წყაროს/დანიშნულების ან მსგავსი ნიშნების საფუძველზე და AML/CTF კონტროლის მიზნით განიხილება ერთობლივად. (კორპორაციული განმარტება AML მიზნებისთვის). (fms.gov.ge)'),
    (93, 'ge', 'დ', 'დამატებითი საკომისიო', 'Additional Fee', 'გადასახადი, რომელიც ეკისრება კლიენტს კაპიტალის საკმარისობის კოეფიციენტის (CAR) დარღვევის შემთხვევაში კომპანიის ხარჯების დასაფარად.'),
    (153, 'ge', 'დ', 'დამხმარე სერვისები', 'Ancillary Services', 'დამატებითი მომსახურებები, რომლებიც გაწეულია საინვესტიციო მომსახურებასთან ერთად, მათ შორის ანგარიშგება, შენახვა, კლირინგი, კონსულტაცია და სხვა.'),
    (238, 'ge', 'დ', 'დასაბუთებული ვარაუდი', 'Reasonable Assumption / Reasonable Grounds', 'ფაქტებზე, დოკუმენტებზე, ქცევით ნიშნებზე, ტრანზაქციულ მოდელებზე ან სხვა ობიექტურ მონაცემებზე დაფუძნებული დასკვნა/ვარაუდი, რომელიც საკმარისია AML/CTF მიზნებისთვის საეჭვო/უჩვეულო გარიგების დასაფიქსირებლად, დამატებითი კვლევის დასაწყებად და/ან შეტყობინების მისამართით მოქმედებისათვის. (insurance.gov.ge)'),
    (194, 'ge', 'დ', 'დაუნთაიმი', 'Downtime', 'სერვისის ან აღჭურვილობის მიუწვდომლობის პერიოდი.'),
    (192, 'ge', 'დ', 'დაყოვნება', 'Latency', 'სისტემის ან სერვისის რეაგირების დაყოვნება.'),
    (124, 'ge', 'დ', 'დემატერიალიზაცია', 'Dematerialization (DEMAT)', 'ფასიანი ქაღალდების გადაყვანა არადოკუმენტურ ფორმაში დეპოზიტარის მეშვეობით აღრიცხვით.'),
    (222, 'ge', 'დ', 'დერივატივი', 'Derivative', 'ხელშეკრულება (კონტრაქტი), რომლის საფუძველზეც მხარეები იღებენ უფლებას ან ვალდებულებას განახორციელონ გარკვეული მოქმედებები საბაზო აქტივთან დაკავშირებით.'),
    (88, 'ge', 'დ', 'დეფოლტის ფონდი', 'Default Fund', 'კლირინგული ორგანიზაციის სარეზერვო ფონდი, რომელიც გამოიყენება მონაწილეთა მიერ ვალდებულებების შეუსრულებლობის შემთხვევაში ზარალების დასაფარად.'),
    (11, 'ge', 'ე', 'ევრობონდები', 'Eurobond', 'ობლიგაციები, ნომინირებული იმ ვალუტაში, რომელიც განსხვავდება ემიტენტის ქვეყნის ვალუტისგან, გამოშვებული უცხოეთის მთავრობების, სახელმწიფო ორგანოების, საერთაშორისო ორგანიზაციების, მსხვილი კორპორაციებისა და სხვა იურიდიული პირების მიერ და მიმოქცევაში მყოფი საერთაშორისო კაპიტალის ბაზრებზე.'),
    (224, 'ge', 'ე', 'ელექტრონული დოკუმენტი', 'Electronic Document', 'ელექტრონულ ფორმაში ფიქსირებული ინფორმაცია, რომელიც შეიცავს სავალდებულო რეკვიზიტებს და იძლევა მისი შინაარსის, ავტორის და ფორმირების დროის ერთმნიშვნელოვანი იდენტიფიკაციის შესაძლებლობას. ელექტრონულ დოკუმენტს აქვს ქაღალდის დოკუმენტის ტოლფასი იურიდიული ძალა, იმ პირობით, რომ გამოიყენება დადგენილი ელექტრონული დადასტურების საშუალება (ელექტრონული ხელმოწერა, SSO- ავთენტიფიკაცია, კვალიფიციური იდენტიფიკაციის საშუალებები ან სხვა მეთოდი, რომელიც აღიარებულია რეგულატორის მიერ).'),
    (67, 'ge', 'ე', 'ელექტრონული ხელმოწერა', 'E-Signature', 'ელექტრონულ ფორმაში არსებული ინფორმაცია, რომელიც მიერთებულია სხვა ელექტრონულ მონაცემებს ან ლოგიკურად არის მათთან დაკავშირებული და გამოიყენება ხელმომწერის იდენტიფიკაციისა და ელექტრონული დოკუმენტის მთლიანობის დადასტურებისთვის. ამ რეგლამენტის ფარგლებში გამოიყენება მარტივი ელექტრონული ხელმოწერა საქართველოს მოქმედი კანონმდებლობისა და ელექტრონული ხელმოწერის გამოყენების №8 შესახებ შეთანხმების (რეგლამენტის დანართი) მნიშვნელობით.'),
    (204, 'ge', 'ე', 'ემიტენტზე კონცენტრაციის ლიმიტი', 'Issuer Concentration Limit', 'ერთ ემიტენტზე დასაშვები მაქსიმალური ექსპოზიციის ლიმიტი.'),
    (156, 'ge', 'ე', 'ექსპოზიცია', 'Exposure', 'ღია პოზიციასთან დაკავშირებული რისკის საერთო მოცულობა.'),
    (162, 'ge', 'ე', 'ექსპოზიციის ლიმიტები', 'Exposure Limits', 'ფინანსურ ინსტრუმენტზე და/ან პორტფელზე დასაშვები მაქსიმალური რისკის დონე.'),
    (5, 'ge', 'ვ', 'ვალუტა', 'Currency', 'ეროვნული ან უცხოური ფულადი ერთეულები, მათ შორის საქართველოს ეროვნული ვალუტა — ლარი.'),
    (181, 'ge', 'ვ', 'ვალუტის ექსპოზიცია (FX)', 'FX Exposure', 'ღია სავალუტო პოზიცია.'),
