    (184, 'ge', 'ვ', 'ვალუტის მგრძნობელობა', 'FX Sensitivity', 'პორტფელის რეაქცია სავალუტო კურსის ცვლილებაზე.'),
    (151, 'ge', 'ვ', 'ვალუტის ოპერაციები საინვესტიციო მომსახურებასთან დაკავშირებით', 'FX Transactions related to Investment Services', 'სავალუტო გარიგებები, რომლებიც ხორციელდება კლიენტის საინვესტიციო ოპერაციების შესრულების ან მომსახურების მიზნით.'),
    (182, 'ge', 'ვ', 'ვალუტური გაპი (FX GAP)', 'FX GAP', 'აქტივებსა და ვალდებულებებს შორის შეუსაბამობა კონკრეტულ ვალუტაში.'),
    (32, 'ge', 'ვ', 'ვაჭრობის ორგანიზატორი', 'Exchange / ATS', 'იურიდიული პირი, მათ შორის უცხოური (ბირჟა, სავაჭრო პლატფორმა, ბროკერი, ბანკი), რომელიც უზრუნველყოფს ფასიანი ქაღალდების, ვალუტის, წარმოებული ფინანსური ინსტრუმენტებისა და სხვა ინსტრუმენტების ორგანიზებული ბაზრის ფუნქციონირებას შესაბამისი იურისდიქციის კანონმდებლობისა და საკუთარი სავაჭრო წესების შესაბამისად.'),
    (59, 'ge', 'ვ', 'ვაჭრობის საკომისიო', 'Trading Fee', 'ბროკერის დამატებითი ანაზღაურება კლიენტის დავალებით საბირჟო გარიგებების განხორციელებისთვის, ტარიფების შესაბამისად.'),
    (43, 'ge', 'ვ', 'ვაჭრობის წესები', 'Exchange Rules', 'ვაჭრობის ორგანიზატორის წესები, რეგლამენტები, ინსტრუქციები, პროცედურები, ნორმატიული დოკუმენტები ან მოთხოვნები, რომლებიც სავალდებულოა ან რეკომენდებულია შესაბამის სავაჭრო პლატფორმაზე ვაჭრობის ყველა მონაწილისთვის.'),
    (235, 'ge', 'ვ', 'ვერიფიკაცია', 'Verification', 'ისეთი ინფორმაციის/დოკუმენტების მიღება და შემოწმება, რომლებიც ანგარიშვალდებულ პირს საშუალებას აძლევს დაადასტუროს კლიენტის (და საჭიროებისას — წარმომადგენლის/ბენეფიციარის) იდენტიფიკაციის მონაცემების სისწორე და ავთენტურობა. (Бухгалтерский надзор)'),
    (158, 'ge', 'ვ', 'ვოლატილობა', 'Volatility', 'ფასების ცვალებადობის სტატისტიკური საზომი.'),
    (61, 'ge', 'ზ', 'ზემდგომი ბროკერი', 'Prime Broker / Executing Broker', 'უცხოური ან ქართული ბაზრის პროფესიონალი მონაწილე, რომელსაც აქვს შესაბამისი ლიცენზია ან ნებართვა საბროკერო საქმიანობის განსახორციელებლად და რომლის მეშვეობითაც ბროკერი ასრულებს კლიენტების დავალებებს უცხოურ სავაჭრო პლატფორმებზე და/ან ორგანიზებულ ბაზრებზე.'),
    (62, 'ge', 'თ', 'თრეიდი', 'Trade Execution / Filled Order', 'კლიენტის დავალება, რომელიც შესრულებულია სრულად ან ნაწილობრივ და რომელსაც ბროკერის სისტემაში მინიჭებული აქვს უნიკალური ნომერი.'),
    (234, 'ge', 'ი', 'იდენტიფიკაცია', 'Identification', 'კლიენტის, მისი წარმომადგენლის/უფლებამოსილი პირის და/ან ბენეფიციარი მესაკუთრის იდენტიფიკაციის მონაცემების მიღება და ფიქსაცია, დადგენილი AML/CTF მოთხოვნების შესაბამისად. (fms.gov.ge)'),
    (15, 'ge', 'ი', 'ინდივიდუალური საინვესტიციო რეკომენდაცია', 'Personalized Investment Advice', 'კონკრეტული კლიენტისადმი მიმართული ინფორმაცია ფასიანი ქაღალდების, წარმოებული ფინანსური ინსტრუმენტების, ვალუტისა და/ან მათთან დაკავშირებული გარიგებების შესახებ, რომელიც მომზადებულია კლიენტის მიზნების, გამოცდილების, ფინანსური მდგომარეობისა და რისკისადმი დამოკიდებულების გათვალისწინებით და შეესაბამება საქართველოს კანონმდებლობას, ნბგ-ს ნორმატიულ აქტებსა და ბროკერის შიდა დოკუმენტებს, რომლებიც არეგულირებს საინვესტიციო კონსულტირების საქმიანობას.'),
    (3, 'ge', 'ი', 'ინვესტორთა უფლებების დაცვის ძირითადი სტანდარტი', 'Fiduciary Standard', 'ინვესტორთა უფლებებისა და ინტერესების დაცვის ძირითადი პრინციპი, რომელიც განსაზღვრულია საქართველოს კანონმდებლობით.'),
    (214, 'ge', 'ი', 'ინფრასტრუქტურული დაწესებულება', 'Infrastructure Institution', 'ზედა დონის ბროკერი, კასტოდიანი, ცენტრალური დეპოზიტარი, ცენტრალური კონტრაგენტი, კლირინგული ორგანიზაცია და ფინანსური ბაზრის სხვა ინფრასტრუქტურული ორგანიზაციები.'),
    (185, 'ge', 'ი', 'ინციდენტების სიხშირე', 'Incident Frequency', 'ოპერაციული ინციდენტების რაოდენობა განსაზღვრულ პერიოდში.'),
    (96, 'ge', 'კ', 'კაპიტალის საკმარისობის კოეფიციენტი', 'Capital Adequacy Ratio (CAR)', 'მაჩვენებელი, რომელიც ასახავს აქტივების წმინდა ღირებულების თანაფარდობას მარჟინალური მოთხოვნებისა და'),
    (135, 'ge', 'კ', 'კვალიფიციური კონტრაგენტი', 'Eligible Counterparty', 'მსხვილი და გამოცდილ ბაზრის მონაწილე, რომელიც ახორციელებს მნიშვნელოვან სავაჭრო ოპერაციებს (ფინანსური ინსტიტუტები, ფონდები და სხვა).'),
    (2, 'ge', 'კ', 'კითხვარის მონაცემები', 'KYC Data', 'ინფორმაცია კლიენტის, მისი წარმომადგენლებისა და ბენეფიციარების შესახებ, რომელიც ბროკერს მიეწოდება ანკეტის შევსებისა და შესაბამისი დოკუმენტების წარდგენის ფარგლებში.'),
    (216, 'ge', 'კ', 'კლიენტი', 'Client', 'ბროკერის კლიენტი — ფიზიკური ან იურიდიული პირი, რომელსაც გააჩნია ხელშეკრულებითი ურთიერთობა ბროკერთან და მიმართავს ბროკერს ფინანსურ ინსტრუმენტებთან დაკავშირებული გარიგებების დასადებად. კლიენტი ანიჭებს ბროკერს შესაბამის უფლებამოსილებას გარიგებების დასადებად, უზრუნველყოფს საჭირო რესურსებს და იღებს დაკავშირებულ რისკებს.'),
    (13, 'ge', 'კ', 'კლიენტის აქტივები', 'Client Assets', 'კლიენტის ფულადი სახსრები, ფასიანი ქაღალდები, რომლებიც განთავსებულია საბროკერო ანგარიშზე, ძვირფასი მეტალები, აგრეთვე ფულადი სახსრები, ფასიანი ქაღალდები და ძვირფასი მეტალები, რომლებიც უნდა ჩაირიცხოს საბროკერო ანგარიშზე ბროკერის მიერ კლიენტის ინტერესებში დადებული გარიგებების ანგარიშსწორების შედეგად.'),

    (112, 'ge', 'კ', 'კლიენტის აქტივები (დამტკიცებული)', 'Client’s Assets (Confirmed)', 'კლიენტის ფულადი სახსრები და ფასიანი ქაღალდები, რომლებიც შეესაბამება კომპანიის მოთხოვნებს და ხელმისაწვდომია უზრუნველყოფისათვის.'),
    (40, 'ge', 'კ', 'კლიენტის ბრძანება / დავალება', 'Customer Order / Client Instruction', 'განკარგულებითი ხასიათის შეტყობინება, რომელიც კლიენტმა წარადგინა ბროკერისთვის გარიგების დადებისა და/ან ოპერაციის განხორციელების მიზნით კლიენტის ინტერესებში.'),
    (138, 'ge', 'კ', 'კლიენტის განკარგულების მიღება და გადაცემა', 'Reception and Transmission of Orders', 'მომსახურება, რომელიც მოიცავს კლიენტისგან განკარგულებების მიღებას და მათი მესამე პირებისთვის გადაცემას შესრულების მიზნით.'),
    (104, 'ge', 'კ', 'კლიენტის დავალიანება', 'Client’s Obligations / Indebtedness', 'კლიენტის ყველა სასესხო ვალდებულების ერთობლიობა კომპანიის წინაშე, მათ შორის საკომისიოები, პროცენტები, სესხების დაბრუნება და სხვა გადახდები.'),
    (31, 'ge', 'კ', 'კლიენტის ვალდებულებები', 'Customer Liabilities', 'კლიენტის ყველა ვალდებულება ბროკერის წინაშე ხელშეკრულებებისა და ოპერაციების ფარგლებში, მათ შორის მომსახურებებისა და ხარჯების ანაზღაურება.'),
    (163, 'ge', 'კ', 'კლიენტის კაპიტალი / ექვიტი', 'Equity', 'კლიენტის საკუთარი კაპიტალი, რომელიც მოიცავს ბროკერულ ანგარიშზე არსებულ ფულად სახსრებსა და ფასიან ქაღალდებს, აგრეთვე იმ ფულად სახსრებსა და ფასიან ქაღალდებს, რომლებიც უნდა ჩაირიცხოს ბროკერულ ანგარიშზე კლიენტის ინტერესებში ბროკერის მიერ დადებული გარიგებების ანგარიშსწორების შედეგად.'),
    (1, 'ge', 'კ', 'კლიენტის კითხვარი', 'Client Questionnaire', 'შემკრები ტერმინი, რომელიც მოიცავს ფიზიკური პირის ანკეტასა და იურიდიული პირის ანკეტას (ფორმები მოცემულია №1 ხელშეკრულების დანართში).'),
    (39, 'ge', 'კ', 'კლიენტის პორტფელი', 'Client Portfolio', 'ბროკერის შიდა აღრიცხვის სისტემაში კლიენტის სუბანგარიშების დაჯგუფების სტრუქტურული ერთეული ხელშეკრულების ფარგლებში, რომლის ჭრილშიც ბროკერი ახორციელებს კლიენტის რისკების კონტროლსა და მისი ოპერაციების ანალიზს.'),
    (22, 'ge', 'კ', 'კლიენტის რისკის კატეგორია', 'Client Risk Classification', 'კატეგორია, რომელიც ახასიათებს კლიენტისათვის დასაშვები მაქსიმალური რისკის დონეს ბროკერის რისკების მართვის სისტემაში და განისაზღვრება ბროკერის მიერ ანკეტის და კლიენტის შესახებ სხვა მონაცემების საფუძველზე, ხელშეკრულებითა და ბროკერის შიდა დოკუმენტებით დადგენილი წესით.'),
    (6, 'ge', 'კ', 'კლიენტის რისკ-პროფილი', 'Client Risk Profile', 'რისკების მართვის სისტემის პარამეტრები, რომლებიც გამოიყენება კლიენტის პორტფელთან მიმართებით.'),
    (27, 'ge', 'კ', 'კლიენტის საბალანსო ანგარიში', 'Sub-Account', 'ბროკერის შიდა აღრიცხვის სტრუქტურული ერთეული, რომელიც წარმოადგენს კლიენტის პორტფელის შემადგენელ ნაწილს და განკუთვნილია კლიენტის ქონებისა და ვალდებულებების რაოდენობრივი აღრიცხვისთვის ფასიან ქაღალდებთან, დერივატივებთან, ძვირფას მეტალებთან და ფულადი სახსრებთან დაკავშირებული გარიგებებისა და ოპერაციების ასახვით. ერთი კლიენტის პორტფელის ფარგლებში იხსნება არანაკლებ ერთი სუბანგარიში; პირადი ანგარიშების რაოდენობა და სტრუქტურა განისაზღვრება კლიენტის და/ან ბროკერის მიერ ხელშეკრულების შესაბამისად.'),
    (221, 'ge', 'კ', 'კლიენტის საპროგრამო უზრუნველყოფა', 'Client Software', 'ელექტრონული გამოთვლითი მანქანებისთვის განკუთვნილი პროგრამები, რომლებიც კლიენტს მიეწოდება ბროკერის მიერ და/ან გამოიყენება კლიენტის მიერ ხელშეკრულებისა და მესამე პირებთან დადებული შეთანხმებების შესაბამისად შეტყობინებების გაცვლის, განკარგულებების წარდგენისა და ბროკერის მომსახურებებზე წვდომისათვის.'),
    (139, 'ge', 'კ', 'კლიენტის სახელით განკარგულების შესრულება', 'Execution of Orders on Behalf of Clients', 'ბროკერის მიერ კლიენტის განკარგულებით ფინანსურ ინსტრუმენტებთან დაკავშირებული გარიგებების შესრულება.'),
    (68, 'ge', 'კ', 'კლიენტის ID', 'Client ID / Unique Client Identifier (UCI)', 'პერსონალური ასო-ციფრული კოდი, რომელიც კლიენტს ენიჭება ბროკერის ვებ-საიტზე რეგისტრაციისას და უცვლელია ურთიერთობის მთელი პერიოდის განმავლობაში.'),
    (72, 'ge', 'კ', 'კლირინგის სესია', 'Clearing Session', 'დროის პერიოდი, რომლის განმავლობაში კლირინგული ორგანიზაცია ახორციელებს ღია პოზიციებზე ანგარიშსწორებებს, მარჟის ხელახალ გამოთვლას და მხარეთა ვალდებულებების ფიქსაციას.'),
    (145, 'ge', 'კ', 'კომოდიტების ბაზრის შესახებ აქტი 1936 წლის', 'Commodity Exchange Act (CEA) of 1936', 'კანონი, რომელიც არეგულირებს დერივატივებით, ფიუჩერსებითა და სვოპებით ვაჭრობას CFTC-ის ზედამხედველობის ქვეშ; ფუნქციური ანალოგი MiFIR-ისა (ვაჭრობისა და კლირინგის რეგულირება).'),
    (105, 'ge', 'კ', 'კომპენსაციის თანხა', 'Compensation Sum', 'ფულადი თანხა ან ფასიანი ქაღალდების საბაზრო ღირებულება, რომელიც კლიენტმა უნდა გადაიხადოს მარჟინალური გარიგებების შესრულებასთან დაკავშირებით.'),
    (25, 'ge', 'კ', 'კონვერტაცია', 'Currency Conversion', 'ნაღდი ფულის გარეშე ფორმით განხორციელებული საბირჟო გარეთ კონვერტაცია, ანუ კლიენტის საწყისი ვალუტის გაცვლა სამიზნე ვალუტაზე შეთანხმებული კურსით, მათ შორის ვალდებულების ვალუტის შეცვლის მიზნით. კონვერტაციაზე გაცემულ დავალებაში (მათ შორის პირობით დავალებაში) ვალდებულებების შეცვლის მიზნით საწყის ვალუტად მიიჩნევა ვალუტა, რომელზეც იცვლება მოქმედი ვალდებულების ვალუტა; სამიზნე ვალუტად — ვალუტა, რომელშიც ვალდებულება გამოხატულია ასეთი დავალების (პირობითი დავალების) წარდგენის მომენტში.'),
    (171, 'ge', 'კ', 'კონტრაგენტის ექსპოზიცია', 'Counterparty Exposure', 'კონტრაგენტთან დაკავშირებული რისკის ოდენობა.'),
    (172, 'ge', 'კ', 'კონტრაგენტის სანდოობის ქულა', 'Counterparty Reliability Score', 'კონტრაგენტის ფინანსური და ტექნოლოგიური და/ან ოპერაციული მდგრადობის შეფასება (თუ გამოყენებადია).'),
    (174, 'ge', 'კ', 'კონტრაგენტის SLA-ს დარღვევის მაჩვენებელი', 'Counterparty SLA Breach Indicator', 'მომსახურების პროვაიდერის მიერ SLA-ის დარღვევის ფაქტის მაჩვენებელი.'),
    (92, 'ge', 'კ', 'კონტრაქტის მულტიპლიკატორი', 'Contract Multiplier', 'კოეფიციენტი, რომელიც გამოიყენება ფიუჩერსული ან ოფციონური კონტრაქტის სრული ღირებულების განსასაზღვრად (ფასი × მულტიპლიკატორი).'),
    (236, 'ge', 'კ', 'კონფიდენციალური ინფორმაცია', 'Confidential Information', 'ნებისმიერი ინფორმაცია, რომელიც მიღებულია AML/CTF პროცედურების ფარგლებში (მათ შორის კლიენტის მონაცემები, CDD/KYC მასალები, ტრანზაქციების მონიტორინგის შედეგები, ეჭვის საფუძვლები და შეტყობინების ფაქტი/შინაარსი), და ექვემდებარება დაცვისა და გამჟღავნების შეზღუდვებს კანონითა და შიდა პოლიტიკებით. (fms.gov.ge)'),
    (203, 'ge', 'კ', 'კონცენტრაციის ლიმიტი', 'Concentration Limit', 'ერთი ფინანსური ინსტრუმენტის ან ერთი კონტრაგენტის მიმართ დასაშვები მაქსიმალური ექსპოზიციის ლიმიტი.'),
    (94, 'ge', 'კ', 'კორექტირებული საწყისი მარჟა', 'Adjusted Initial Margin (AIM)', 'კლიენტის ყველა ღია პოზიციისა და ორდერის მიხედვით მარჟინალური მოთხოვნების ერთობლივი ოდენობა.'),
    (125, 'ge', 'კ', 'კორპორატიული ქმედებები', 'Corporate Actions', 'მოვლენები, რომლებიც გავლენას ახდენს ფასიან ქაღალდებზე (დივიდენდები, სპლიტები, კონვერტაციები და სხვა).'),
    (50, 'ge', 'კ', 'კოტირების ვალუტა', 'Quote Currency', 'ვალუტა, რომელშიც გამოხატულია ინსტრუმენტის ფასი ან რომელშიც ხორციელდება კონვერტაციული გარიგების ანგარიშსწორება.'),
    (207, 'ge', 'ლ', 'ლიკვიდობის შეზღუდვა', 'Liquidity Constraint', 'პოზიციების შეზღუდვა ფინანსური ინსტრუმენტის ლიკვიდობის გათვალისწინებით.'),
    (179, 'ge', 'ლ', 'ლიკვიდურობის დაფარვის კოეფიციენტი', 'Liquidity Coverage Ratio', 'ლიკვიდური აქტივებისა და ვალდებულებების თანაფარდობა.'),
    (175, 'ge', 'ლ', 'ლიკვიდურობის ქულა', 'Liquidity Score', 'ფინანსური ინსტრუმენტის ლიკვიდურობის მაჩვენებელი.'),
    (187, 'ge', 'მ', 'მარკეტ-დატის დაყოვნება', 'Market Data Delay', 'აქტუალური საბაზრო კოტირებების შესახებ ინფორმაციის დაყოვნება.'),
    (102, 'ge', 'მ', 'მარჟინალური გარიგება', 'Margin Transaction', 'გარიგება, რომელიც კლიენტის მიერ ხორციელდება ბროკერის მიერ მიწოდებული საკრედიტო ბერკეტის (მარჟინალური სესხის) გამოყენებით.'),
    (101, 'ge', 'მ', 'მარჟინალური მოთხოვნები', 'Margin Requirements', 'უზრუნველყოფის ოდენობა, რომელსაც კომპანია მოითხოვს კლიენტისგან მარჟინალური პოზიციის გახსნისა და შენარჩუნებისათვის.'),
    (100, 'ge', 'მ', 'მარჟინალური სესხი', 'Margin Loan', 'ფულადი სახსრები ან ფასიანი ქაღალდები, რომლებიც კომპანიის მიერ მიეწოდება კლიენტს მარჟინალური გარიგებების შესასრულებლად.'),
    (170, 'ge', 'მ', 'მარჟინის დახურვის განმაპირობებელი', 'Margin Close-Out Trigger', 'უზრუნველყოფის დონე, რომლის მიღწევისას ბროკერი იწყებს კლიენტის პოზიციების იძულებით დახურვას.'),
    (169, 'ge', 'მ', 'მარჟინის ქოლის განმაპირობებელი', 'Margin Call Trigger', 'მარჟის დონე, რომლის მიღწევისას კლიენტს ეგზავნება მარჟინალური მოთხოვნა (დამატებითი უზრუნველყოფის შეტანა ან პოზიციის ნაწილობრივი/სრული დახურვა).'),
    (99, 'ge', 'მ', 'მარჟინ-კოლი', 'Margin Call', 'ბროკერის შეტყობინება კლიენტისთვის ანგარიშის შევსების ან პოზიციების დახურვის აუცილებლობის შესახებ მოთხოვნილი CAR-ის დონის აღსადგენად.'),
    (98, 'ge', 'მ', 'მარჟირებადი აქტივები', 'Marginable Assets', 'კლიენტის აქტივები, რომლებიც შეიძლება გამოყენებულ იქნეს უზრუნველყოფად მარჟინალური გარიგებების ფარგლებში.'),
    (213, 'ge', 'მ', 'მარჟის დახურვის დონე / ლიკვიდაციის დონე, დახურვა', 'Margin Close-Out Level / Liquidation Level, Close- Out', 'უზრუნველყოფის ის დონე, რომლის მიღწევისას ბროკერი იწყებს კლიენტის პოზიციების იძულებით დახურვას.'),
    (168, 'ge', 'მ', 'მარჟის დონე', 'Margin Level', 'კლიენტის კაპიტალისა და მოთხოვნილი მარჟის თანაფარდობა.'),
    (167, 'ge', 'მ', 'მარჟის ზღვარი', 'Maintenance Margin (MM)', 'ღია პოზიციების შენარჩუნებისთვის აუცილებელი მინიმალური უზრუნველყოფა.'),
    (202, 'ge', 'მ', 'მაქსიმალური ლევერიჯი', 'Maximum Leverage', 'დასაშვები მაქსიმალური საკრედიტო ბერკეტი.'),
    (128, 'ge', 'მ', 'მეორადი საჯარო შეთავაზება', 'Secondary Public Offering (SPO)', 'კომპანიის აქციების დამატებითი ემისია, რომელიც უკვე არის ბირჟაზე მიმოქცევაში.'),
    (198, 'ge', 'მ', 'მეორეული მარკეტ-დათა', 'Secondary Market Data', 'ფასების შესახებ ინფორმაცია, მიღებული მონაცემთა აგრეგატორებისგან.'),
    (89, 'ge', 'მ', 'მიმდინარე მარჟა', 'Maintenance Margin', 'მარჟის მინიმალური დონე, რომლის შენარჩუნებაც კლიენტს ევალება ღია პოზიციების დასაცავად.'),
    (71, 'ge', 'მ', 'მიმდინარე ცვლადი მარჟა', 'Mark-to-Market Margin', 'ცვლადი მარჟა, რომელიც კლირინგული ორგანიზაციის მიერ გამოითვლება კლირინგის სესიის განმავლობაში ცვლადი მარჟის გამოთვლის ფორმულის მიხედვით შესაბამისი i-ე ვადიანი კონტრაქტის მიმდინარე საანგარიშო ფასის გამოყენებით. შესაბამის ვალუტაში მიმდინარე ცვლადი მარჟის ჯამური ოდენობა აყალიბებს კლიენტის ვალდებულებებს ან მოთხოვნებს და შედის შესაბამისი ვალუტის გეგმიურ პოზიციაში. კლიენტი ვალდებულია დამოუკიდებლად აკონტროლოს მიმდინარე ცვლადი მარჟა.'),
    (90, 'ge', 'მ', 'მიწოდების თვე', 'Delivery Month', 'კალენდარული თვე, რომლის განმავლობაში ხდება ფიუჩერსული კონტრაქტის შესრულება ან მიწოდება.'),
    (78, 'ge', 'მ', 'მიწოდების შეტყობინება', 'Delivery Notice', 'დოკუმენტი, რომელიც იგზავნება კლირინგის მონაწილის მიერ კონტრაქტის შესრულების განზრახვის შემთხვევაში საბაზო აქტივის მიწოდების გზით.'),
    (109, 'ge', 'მ', 'მოკლე პოზიცია', 'Short Position', 'პოზიცია, რომელიც წარმოიშობა ფასიანი ქაღალდების დაუფარავი გაყიდვისას (ფასის შემცირების მოლოდინი).'),
    (157, 'ge', 'მ', 'მომგებიანობა', 'Return', 'ინსტრუმენტის ღირებულების ცვლილება განსაზღვრული პერიოდის განმავლობაში.'),

    (189, 'ge', 'მ', 'მონაცემების მთლიანობის ინდიკატორი', 'Data Integrity Indicator', 'მონაცემების სისწორისა და სრულყოფილობის მაჩვენებელი.'),
    (84, 'ge', 'ნ', 'ნეტინგი', 'Netting', 'მხარეებს შორის ურთიერთსაპირისპირო ვალდებულებების ჩათვლის პროცესი ანგარიშსწორებების საერთო მოცულობისა და რისკების შემცირების მიზნით.'),
    (218, 'ge', 'ო', 'ონბორდინგის მოდული', 'Onboarding System', 'ბროკერისა და კლიენტის მიერ გამოყენებული ავტორიზებული ორგანიზაციულ-ტექნიკური დისტანციური მომსახურების სისტემა (პროგრამული უზრუნველყოფა), რომელიც უზრუნველყოფს კლიენტის ონბორდინგის პროცედურას, მათ შორის კლიენტის დისტანციურ იდენტიფიკაციას, დოკუმენტების გაცვლას, საბროკერო ხელშეკრულების დადებასა და საბროკერო ანგარიშის გახსნას. წვდომა ხორციელდება ვებ-სერვისისა და/ან მობილური აპლიკაციის მეშვეობით.'),
    (35, 'ge', 'ო', 'ოფიციალური გაცვლითი კურსი', 'Official Exchange Rate', 'ვალუტების კურსი, დადგენილი და გამოქვეყნებული საქართველოს ეროვნული ბანკის (ნბგ) მიერ.'),
    (82, 'ge', 'ო', 'ოფციონის ექსპირაცია', 'Option Expiration', 'ოფციონის მოქმედების დასრულების თარიღი, რომლის შემდეგ კონტრაქტი კარგავს ძალას და წყვეტს მიმოქცევას.'),
    (79, 'ge', 'ო', 'ოფციონის პრემია', 'Option Premium', 'ფასი, რომელსაც ოფციონის მყიდველი უხდის გამყიდველს საბაზო აქტივის განსაზღვრულ ფასად ყიდვის ან გაყიდვის უფლებისთვის (მაგრამ არა ვალდებულებისთვის).'),
    (81, 'ge', 'ო', 'ოფციონის ტიპი', 'Option Type (Call / Put)', 'განსაზღვრავს უფლებას საბაზო აქტივის შეძენაზე (Call) ან გაყიდვაზე (Put) ფიქსირებულ ფასად.'),
    (239, 'ge', 'პ', 'პასუხისმგებელი თანამშრომელი', 'Responsible Employee', 'ბროკერის მიერ განსაზღვრული თანამშრომელი, რომელსაც ეკისრება AML/CTF შიდა კონტროლების, მონიტორინგის, კლიენტის დადასტურების (CDD/KYC), ეჭვიანი შემთხვევების ესკალაციის და შესაბამის ორგანოებთან/კომპეტენტურ ერთეულებთან ურთიერთქმედების ფუნქციები, შიდა პოლიტიკებისა და კანონმდებლობის შესაბამისად. (საქართველოს ეროვნული ბანკი)'),
    (28, 'ge', 'პ', 'პირადი კაბინეტი', 'Client Portal', 'ბროკერისა და კლიენტის მიერ გამოყენებული ავტორიზებული ორგანიზაციულ-ტექნიკური დისტანციური მომსახურების სისტემა (პროგრამული უზრუნველყოფა), რომელიც ინტერნეტის საშუალებით უზრუნველყოფს ბროკერის მომსახურებებზე, კლიენტის ანგარიშებსა და ოპერაციებზე წვდომას. პირადი კაბინეტი იძლევა ხელშეკრულებების დადებისა და შეწყვეტის, მომსახურებების მიღებისა და მიწოდების, ელექტრონული დოკუმენტებისა და შეტყობინებების გაცვლის შესაძლებლობას. პირადი კაბინეტის უფლებამფლობელია ბროკერი. წვდომა კლიენტს მიეწოდება ვებ-სერვისის (მათ შორის ბროკერის ვებ- საიტზე განთავსებული ბმულის მეშვეობით) და/ან მობილური აპლიკაციის საშუალებით. პირადი კაბინეტი კლიენტს მიეწოდება პროგრამული უზრუნველყოფის „პირადი კაბინეტი“ გამოყენების შეთანხმებისა და კლიენტების დისტანციური მომსახურების პირობების შესაბამისად.'),
    (9, 'ge', 'პ', 'პირადობის დამადასტურებელი დოკუმენტი', 'Government-Issued ID', 'ერთ-ერთი შემდეგი დოკუმენტი: საქართველოს მოქალაქის პასპორტი; საქართველოს მოქალაქის პირადობის მოწმობა (ID Card); საქართველოს მოქალაქის დაბადების მოწმობა (14 წლამდე ასაკის პირებისთვის); უცხო ქვეყნის მოქალაქის პასპორტი; საქართველოში ბინადრობის ნებართვა ან საქართველოს კანონმდებლობით აღიარებული სხვა სათანადო პირადობის დამადასტურებელი დოკუმენტი.'),
    (197, 'ge', 'პ', 'პირველადი მარკეტ-დათა', 'Primary Market Data', 'ფასების შესახებ ინფორმაცია, მიღებული უშუალოდ ბირჟებიდან.'),
    (127, 'ge', 'პ', 'პირველადი საჯარო შეთავაზება', 'Initial Public Offering (IPO)', 'კომპანიის აქციების განთავსება ბირჟაზე კაპიტალის მოზიდვის მიზნით.'),
    (63, 'ge', 'პ', 'პირობითი ბრძანება', 'Conditional Order', 'დავალება, რომელიც მოცემულია ხელშეკრულების ტექსტში, მის დანართებში ან კლიენტსა და ბროკერს შორის გაფორმებულ ცალკეულ შეთანხმებაში და რომლის შესრულებას ბროკერი ახორციელებს მხოლოდ მასში მითითებული პირობების შესრულების შემთხვევაში.'),
    (237, 'ge', 'პ', 'პოლიტიკურად აქტიური პირი (PEP)', 'Politically Exposed Person (PEP)', 'პირი, რომელსაც ეკავა/უკავია მნიშვნელოვანი საჯარო ფუნქცია, აგრეთვე მისი ოჯახის წევრები და მჭიდროდ დაკავშირებული პირები — AML/CTF კანონმდებლობისა და მარეგულირებლის მოთხოვნების შესაბამისად. (fms.gov.ge)'),
    (54, 'ge', 'პ', 'პორტფელის ღირებულება', 'Portfolio Value', 'ერთი პორტფელის ფარგლებში კლიენტის გეგმიური პოზიციების ერთობლიობა, გამოხატული საქართველოს ლარში (ან უცხოურ ვალუტაში, თუ ეს ხელშეკრულებით არის გათვალისწინებული). პორტფელის ღირებულება, რომელიც ასახულია კლიენტის მიერ შეტყობინებების გაცვლისთვის გამოყენებულ პროგრამულ უზრუნველყოფაში, შეიძლება განსხვავდებოდეს ბროკერის მიერ გამოთვლილი და პირად კაბინეტში გამჟღავნებული ღირებულებისგან; კლიენტი ვალდებულია დამოუკიდებლად აკონტროლოს თავისი ნებისმიერი პორტფელის ღირებულება.'),
    (134, 'ge', 'პ', 'პროფესიონალი კლიენტი', 'Professional Client', 'კლიენტი, რომელსაც გააჩნია საკმარისი ცოდნა, გამოცდილება და აქტივები რისკების გასაგებად და სარგებლობს შეზღუდული დაცვის დონით MiFID II-ის შესაბამისად.'),
    (108, 'ge', 'პ', 'პროცენტები', 'Interest', 'თანხა, რომელიც ირიცხება სესხებული ფულადი სახსრების და/ან ფასიანი ქაღალდების გამოყენებისთვის მარჟინალური გარიგებების ფარგლებში.'),
    (122, 'ge', 'რ', 'რედომიცილება', 'Redomiciliation', 'იურიდიული პირის ან ფონდის ხელახალი რეგისტრაცია სხვა იურისდიქციაში საკუთრების სტრუქტურის შენარჩუნებით.'),
    (36, 'ge', 'რ', 'რეფერალი', 'Referral Partner', 'იურიდიული პირი, რომელთანაც ბროკერს გაფორმებული აქვს ანაზღაურებადი მომსახურების ხელშეკრულება პოტენციური კლიენტების მოძიებისა და მოზიდვის მიზნით, აგრეთვე ბროკერსა და კლიენტს შორის დოკუმენტბრუნვის ორგანიზებისთვის, მათ შორის ინტერნეტში სპეციალური ვებ-საიტის (ვებ-ინტერფეისის) მეშვეობით.'),
    (159, 'ge', 'რ', 'რისკზე დამოკიდებული ღირებულება (VaR)', 'Value-at-Risk (VaR)', 'მაქსიმალური მოსალოდნელი დანაკარგი განსაზღვრული ნდობის ინტერვალის ფარგლებში.'),
    (208, 'ge', 'რ', 'რისკის წონა', 'Risk Weight', 'რისკის კოეფიციენტი, რომელიც გამოიყენება საწყისი და მხარდამჭერი მარჟის (IM/MM) გაანგარიშებისას.'),
    (165, 'ge', 'რ', 'რისკი დეფოლტის შემთხვევაში (EAD)', 'Exposure at Default (EAD)', 'ზარალის რისკი დეფოლტის შემთხვევაში.'),
    (209, 'ge', 'რ', 'რისკ-ჯგუფები', 'Risk Groups', '(სУР) ბროკერის რისკების მართვის სისტემის პარამეტრების ერთობლიობა, რომელიც გამოიყენება კლიენტის კონკრეტულ პორტფელზე. რისკ-ჯგუფების ჩამონათვალი და მათი პარამეტრები განისაზღვრება ბროკერის მიერ და ქვეყნდება ბროკერის ვებგვერდზე.'),
    (86, 'ge', 'ს', 'საანგარიშსწორებო (საკლირინგო) ანგარიში', 'Settlement Account', 'სპეციალური ანგარიში, რომელიც გამოიყენება კლირინგული ანგარიშსწორებებისა და მონაწილეებს შორის ურთიერთანგარიშსწორებების ჩასატარებლად.'),
    (80, 'ge', 'ს', 'საბაზო აქტივი', 'Underlying Asset', 'ფინანსური ინსტრუმენტი, საქონელი ან მაჩვენებელი, რომლის საფუძველზეც იქმნება წარმოებული ფინანსური ინსტრუმენტი (დერივატივი). ასეთ აქტივად შეიძლება იყოს ფასიანი ქაღალდი, საქონელი, ვალუტა, საპროცენტო განაკვეთი ან სხვა მაჩვენებლები.'),
    (41, 'ge', 'ს', 'საბაზრო ბრძანება', 'Market Order', 'გარიგების დადების დავალება იმ ფასად, რომელიც ბროკერისთვის ხელმისაწვდომია შესაბამის ვაჭრობებზე დავალების შესრულების მომენტში (ფასის ლიმიტის მითითების გარეშე). ვაჭრობის ორგანიზატორს შეუძლია დააწესოს ფასის გადახრის მაქსიმალური ზღვარი ასეთი დავალებების შესრულებისას; აღნიშნული ინფორმაციის მიღება კლიენტს შეუძლია შესაბამისი ვაჭრობის ორგანიზატორის ოფიციალურ ვებგვერდზე.'),
    (119, 'ge', 'ს', 'საბაზრო მონაცემები რეალურ დროში', 'Real-time Market Data', 'კოტირებებისა და ვაჭრობის შესახებ ინფორმაციის ნაკადი, რომელიც მიეწოდება გამოწერის საფუძველზე.'),
    (14, 'ge', 'ს', 'საბროკერო ანგარიში', 'Brokerage Account', 'ბროკერის შიდა აღრიცხვის სისტემაში არსებული სტრუქტურული ერთეული, რომელიც გამოიყენება კლიენტის ქონების მოძრაობასთან დაკავშირებული ოპერაციების შესახებ ინფორმაციის დაჯგუფებისთვის, მათ შორის ტარიფული გეგმის გამოყენების მიზნებისთვის.'),
    (232, 'ge', 'ს', 'საეჭვო გარიგება', 'Suspicious Transaction', 'გარიგება/ოპერაცია (მათ შორის მცდელობა), რომელთან დაკავშირებითაც არსებობს დასაბუთებული ეჭვი/საფუძველი მიიჩნიოს, რომ იგი შეიძლება უკავშირდებოდეს ფულის გათეთრებას, ტერორიზმის დაფინანსებას, სანქციების/აკრძალვების გვერდის ავლას ან სხვა არალეგალურ მიზანს, და შესაბამისად ექვემდებარება შეფასებასა და, საჭიროებისას, შეტყობინებას შესაბამის ორგანოში. (insurance.gov.ge)'),
    (240, 'ge', 'ს', 'საეჭვო ზონა', 'Suspicious Zone', 'კორპორაციული ტერმინი (არ არის სავალდებულო ლეგალური დეფინიცია): მაღალი AML/CTF რისკის მქონე გეოგრაფიული ზონა/იურისდიქცია, საქმიანობის სფერო, კლიენტთა სეგმენტი ან ოპერაციული არხი, რომელიც განსაზღვრულია ბროკერის რისკების შეფასებით და/ან კომპეტენტური ორგანოების (მათ შორის ნბგ/ფმს) კომუნიკაციებით, და რომლის მიმართაც გამოიყენება გაძლიერებული კონტროლი (EDD/მონიტორინგი). (საქართველოს ეროვნული ბანკი)'),
    (200, 'ge', 'ს', 'სავარაუდო ფასები', 'Reference Prices', 'აქტივების შეფასებისთვის გამოყენებული ფასები.'),
    (60, 'ge', 'ს', 'სავაჭრო დღე', 'Trading Session / Market Day', 'დროის პერიოდი, რომლის განმავლობაში ვაჭრობის ორგანიზატორები ახორციელებენ ვაჭრობას. ხელმისაწვდომი ვაჭრობის ორგანიზატორების ჩამონათვალი და მათი გრაფიკი გამოქვეყნებულია ბროკერის ვებგვერდზე.'),
