    (146, 'ge', 'ს', 'საინვესტიციო კომპანიების შესახებ აქტი 1940 წლის და საინვესტიციო მრჩეველთა შესახებ აქტი 1940 წლის', 'Investment Company Act of 1940 & Investment Advisers Act of 1940', 'SEC-ის ნორმატიული ბაზა, რომელიც არეგულირებს ფონდებისა და საინვესტიციო მრჩევლების საქმიანობას; PRIIPs-ის ანალოგი რისკების გამჟღავნებისა და საცალო ინვესტორების წინაშე ვალდებულებების ნაწილში.'),
    (16, 'ge', 'ს', 'საინვესტიციო კონსულტაცია', 'Investment Advisory Services', 'ბროკერის მომსახურება კლიენტისათვის ინდივიდუალური საინვესტიციო რეკომენდაციების გაწევის მიზნით, №12 ხელშეკრულებისა და რეგლამენტის დანართის, აგრეთვე ბროკერის სხვა შიდა დოკუმენტებისა და საქართველოს კანონმდებლობის შესაბამისად.'),
    (148, 'ge', 'ს', 'საინვესტიციო კონსულტაცია', 'Investment Advice', 'კლიენტისთვის მიწოდებული პერსონალური რეკომენდაცია ფინანსური ინსტრუმენტების შეძენის, გაყიდვის ან შენარჩუნების შესახებ.'),
    (136, 'ge', 'ს', 'საინვესტიციო მომსახურება', 'Investment Services', 'კომპანიის მიერ ლიცენზირებული საქმიანობა, მათ შორის კლიენტის განკარგულებების მიღება და შესრულება, ნდობით მართვა, საინვესტიციო კონსულტაცია და სხვა.'),
