    (132, 'ge', 'ს', 'საცალო კლიენტი', 'Retail Client', 'კლიენტი, რომელიც არ არის პროფესიონალი ან კვალიფიციური კონტრაგენტი და სარგებლობს მაქსიმალური რეგულატორული დაცვით.'),
    (143, 'ge', 'ს', 'საცალო საინვესტიციო და სადაზღვევო პროდუქტების №1286/2014 რეგულაცია (PRIIPs)', 'Regulation (EU) No 1286/2014 on Key Information Documents for Packaged Retail and Insurance-based Investment Products (PRIIPs)', 'ევროკავშირის რეგულაცია, რომელიც ადგენს მოთხოვნებს ძირითადი ინფორმაციის დოკუმენტების (KID) შინაარსსა და წარდგენაზე საცალო ინვესტორების გამჭვირვალობისა და დაცვის უზრუნველსაყოფად.'),
    (70, 'ge', 'ს', 'საწყისი მარჟა', 'Initial Margin / Performance Bond', 'ბროკერის რისკების მართვის სისტემის პარამეტრი, რომელიც განისაზღვრება კლირინგული ორგანიზაციის მიერ და/ან კლირინგული ორგანიზაციის მოთხოვნების საფუძველზე კლიენტის პორტფელის ინდივიდუალური კლირინგული უზრუნველყოფის ოდენობის მიმართ. საწყისი საგარანტიო უზრუნველყოფის მნიშვნელობა, რომელიც აისახება კლიენტის პროგრამულ უზრუნველყოფაში, შეიძლება განსხვავდებოდეს კლირინგული ორგანიზაციის მიერ გამოთვლილი ოდენობისგან; კლიენტი ვალდებულია დამოუკიდებლად აკონტროლოს საწყისი საგარანტიო უზრუნველყოფის ოდენობა.'),
    (166, 'ge', 'ს', 'საწყისი მარჟა (IM)', 'Initial Margin (IM)', 'პოზიციის გახსნისათვის აუცილებელი მინიმალური უზრუნველყოფა (რეგლამენტის შესაბამისად — პოზიციის გახსნისათვის საჭირო უზრუნველყოფის დონე).'),
