    (52, 'ge', 'ს', 'სპეციალიზებული დეპოზიტარი', 'Qualified Custodian', 'ორგანიზაცია, რომელიც ლიცენზიის ან სხვა ნებართვის საფუძველზე ახორციელებს საინვესტიციო ფონდების, საპენსიო სქემების და/ან სხვა კოლექტიური საინვესტიციო ინსტიტუტების სპეციალიზებული დეპოზიტარის საქმიანობას საქართველოს კანონმდებლობის ან შესაბამისი უცხოური იურისდიქციის შესაბამისად.'),
    (176, 'ge', 'ს', 'სპრედის ინდიკატორი', 'Spread Indicator', 'მიმდინარე სპრედის გადახრა საშუალო სტატისტიკური სპრედისგან.'),
    (20, 'ge', 'ს', 'სსს DevEx', 'DevEx Electronic Trading Platform', 'ელექტრონული სავაჭრო სისტემა, შემუშავებული Devexperts Solutions-ის მიერ ფინანსურ ბაზრებზე ოპერაციების განხორციელებაზე ინტერნეტის საშუალებით წვდომის უზრუნველსაყოფად.'),
    (53, 'ge', 'ს', 'სტანდარტული ლოტი', 'Round Lot / Standard Lot', 'ინსტრუმენტის მინიმალური რაოდენობა, რომელიც განსაზღვრულია სავაჭრო პლატფორმის მიერ გარიგებების დასადებად.'),
    (55, 'ge', 'ს', 'სტოპ-ბრძანება', 'Stop Order / Stop-Limit Order', 'ლიმიტირებული ან საბაზრო ფასით საბირჟო გარიგების დადების დავალება გადადებული პირობებით, რომლებიც გათვალისწინებულია პროგრამული უზრუნველყოფის ფუნქციური შესაძლებლობებით და რომლის შესრულება ბროკერისთვის სავალდებულო ხდება დავალებაში მითითებული პირობების დადგომის შემდეგ განაცხადების განთავსებისა და/ან გარიგებების დადების მიზნით.'),
    (160, 'ge', 'ს', 'სტრესული დანაკარგი', 'Stress-Loss', 'პორტფელის დანაკარგი ბაზრის სტრესული ცვლილებების პირობებში.'),
    (201, 'ge', 'ს', 'სტრესული ფასები', 'Stress Prices', 'ფასები, რომლებიც გამოიყენება სტრეს-ტესტირებისათვის.'),
    (117, 'ge', 'ს', 'სტრუქტურირებული პროდუქტები', 'Structured Products', 'კომპლექსური ფინანსური ინსტრუმენტები, რომლებიც აერთიანებს ფასიან ქაღალდებსა და დერივატივებს.'),
    (178, 'ge', 'ს', 'სწრაფი ლიკვიდობის კოეფიციენტი', 'Quick Ratio', 'ვალდებულებების დაფარვა ლიკვიდური აქტივებით.'),
    (228, 'ge', 'ტ', 'ტერორიზმის დაფინანსება', 'Financing of Terrorism', 'ქმედება/ოპერაცია, რომელიც მიმართულია ტერორისტული საქმიანობის, ტერორისტის ან ტერორისტული ორგანიზაციის ფინანსური მხარდაჭერისკენ, მათ შორის სახსრების შეგროვება, გადაცემა ან გამოყენება, მიუხედავად იმისა, არის თუ არა სახსრები კანონიერი წარმოშობის. (fms.gov.ge)'),
    (87, 'ge', 'უ', 'უზრუნველყოფა', 'Collateral', 'აქტივები (ფულადი სახსრები, ფასიანი ქაღალდები), რომლებიც მიეწოდება კლიენტის ვალდებულებების უზრუნველყოფად ბროკერის ან კლირინგის წინაშე.'),
    (111, 'ge', 'უ', 'უნაღდი გარიგება', 'Cashless Transaction', 'გარიგება, რომლის ფარგლებშიც ანგარიშსწორება ხორციელდება უნაღდო გადარიცხვით, ნაღდი ფულის გამოყენების გარეშე.'),
    (233, 'ge', 'უ', 'უჩვეულო გარიგება', 'Unusual Transaction', 'გარიგება/ოპერაცია, რომელიც თავისი მოცულობით, სიხშირით, სტრუქტურით, ეკონომიკური არსით ან კლიენტის პროფილთან შეუსაბამობით ანომალიურია და მოითხოვს დამატებით ანალიზს AML/CTF მიზნებისთვის; უჩვეულო გარიგება შეიძლება, ან არ შეიძლება, გახდეს საეჭვო გარიგება. (საქართველოს ეროვნული ბანკი)'),
